"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[5177],{37510:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"app-showcase-92-real-apps","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/app-showcase-92-real-apps","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2026-08-05-app-showcase-92-real-apps.md","source":"@site/blog/2026-08-05-app-showcase-92-real-apps.md","title":"The App Showcase: 92 real apps, captured live \u2014 and 12 premium flagships","description":"A widget gallery tells you what the parts look like. The new","date":"2026-08-05T00:00:00.000Z","tags":[{"inline":false,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside6","description":"Posts about PySide6"},{"inline":false,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python","description":"Posts about Python"},{"inline":false,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui","description":"Posts about GUI"},{"inline":false,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets","description":"Posts about Custom Widgets"},{"inline":true,"label":"Showcase","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/showcase"},{"inline":false,"label":"news","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/news","description":"Posts about news"}],"readingTime":1.57,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2026-08-05","slug":"app-showcase-92-real-apps","tags":["PySide6","Python","GUI","Custom Widgets","Showcase","news"],"title":"The App Showcase: 92 real apps, captured live \u2014 and 12 premium flagships"},"unlisted":false,"nextItem":{"title":"Custom Widgets 2.3.0: 163 widgets, painted charts, and docs that can\'t go stale","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/custom-widgets-2-3-0-released"}},"content":"A widget gallery tells you what the parts look like. The new\\n[App showcase](/Usage-Examples/AppShowcase) shows the machines: **92 complete,\\nrunnable applications** built with Custom Widgets, every screenshot captured\\nfrom the app itself \u2014 not a mockup.\\n\\n\x3c!-- truncate --\x3e\\n\\n## What\'s in it\\n\\nDashboards for finance, crypto, cash flow, smart-home control and e-commerce\\nanalytics. A three-pane chat client with voice messages and reactions. A music\\nplayer with a cover-flow hero. A node-graph creative studio with a code editor\\nand timeline. Operations consoles, agenda boards, starters \u2014 and roughly\\nseventy single-widget demos, each the shortest runnable answer to \\"how do I\\nwire this up\\".\\n\\n![AuroraChat](/img/showcase-apps/aurorachat.png)\\n\\nEvery card lists the widgets the app actually uses (detected from its real\\nimports, so the list can\'t lie), and every screenshot clicks to full size.\\n\\n## Free apps, and supporter flagships\\n\\nThe single-widget demos, the starters, and teaching apps like GlassHome stay\\nfree in the repo \u2014 they are documentation. The **twelve flagship\\napplications** (marked **PATREON** on the showcase) ship their full source to\\nsupporters: six dashboards, AuroraChat, two operations decks, the jobs table,\\nNodeStudio and RhythmoTune. Each is a production-shaped codebase \u2014 Designer\\nforms, compiled sources, themed stylesheets, managers and workers \u2014 meant to\\nbe the starting point for your own app.\\n\\n![SmartHomeDashboard](/img/showcase-apps/smarthomedashboard.png)\\n\\nScreenshots of everything stay public. The source of the twelve is the\\nsupporter perk.\\n\\n## How to get them\\n\\nSupport the project on [Patreon](https://www.patreon.com/c/spinntv) or grab a\\nplan at [customwidgets.org/pricing](https://customwidgets.org/pricing/) \u2014\\nsupporters get the premium example apps alongside the Pro widget package\\n(DataTable Pro\'s virtualization, grouping, pivot and export). Tutorials and\\nwalkthroughs land on [YouTube](https://www.youtube.com/@SpinnTV).\\n\\nEverything else \u2014 the 163-widget library, the 82 public examples, the whole\\ndocumentation site \u2014 is free under GPLv3, and\\n[2.3.0 is on PyPI now](/blog/custom-widgets-2-3-0-released)."},{"id":"custom-widgets-2-3-0-released","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/custom-widgets-2-3-0-released","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2026-08-05-custom-widgets-2-3-0-released.md","source":"@site/blog/2026-08-05-custom-widgets-2-3-0-released.md","title":"Custom Widgets 2.3.0: 163 widgets, painted charts, and docs that can\'t go stale","description":"Version 2.3.0 is on PyPI \u2014 the largest release in the project\'s history.","date":"2026-08-05T00:00:00.000Z","tags":[{"inline":false,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside6","description":"Posts about PySide6"},{"inline":false,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python","description":"Posts about Python"},{"inline":false,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui","description":"Posts about GUI"},{"inline":false,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets","description":"Posts about Custom Widgets"},{"inline":false,"label":"version","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/version","description":"Posts about version"},{"inline":false,"label":"news","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/news","description":"Posts about news"}],"readingTime":2.7,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2026-08-05","slug":"custom-widgets-2-3-0-released","tags":["PySide6","Python","GUI","Custom Widgets","version","news"],"title":"Custom Widgets 2.3.0: 163 widgets, painted charts, and docs that can\'t go stale"},"unlisted":false,"prevItem":{"title":"The App Showcase: 92 real apps, captured live \u2014 and 12 premium flagships","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/app-showcase-92-real-apps"},"nextItem":{"title":"Complete Guide to Acrylic Effects in Qt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/complete-guide-to-acrylic-effects-in-qt"}},"content":"Version **2.3.0** is on PyPI \u2014 the largest release in the project\'s history.\\nThe catalogue grows to **163 documented widgets**, every example app was\\nrebuilt and verified, and the entire reference documentation is now generated\\nstraight from the code.\\n\\n```bash\\npip install --upgrade QT-PyQt-PySide-Custom-Widgets\\n```\\n\\n\x3c!-- truncate --\x3e\\n\\n## A painted chart family\\n\\nCharts used to lean on Qt Charts; most of the family is now painted directly\\nwith QPainter \u2014 theme-token driven, crisp at any size, and interactive:\\nScatter, Funnel, RangeBar, Radial gauges, Sankey, Candlestick, Beeswarm,\\nDivergingBar, DotMatrix, Sparkline, MiniBar, and the ring/segment\\n[QCustomDonut](/Widgets/QCustomDonut). The\\n[bubble chart](/Widgets/QCustomBubbleChart) ships zoom, drag-pan, search\\ndimming and a painted tooltip card \u2014 not an OS tooltip in sight.\\n\\n![QCustomDonut](/img/showcase/donut.png)\\n\\n## A real data table\\n\\n[QCustomDataTable](/Widgets/QCustomDataTable) brings rich cell renderers\\n(two-line, status dots, currency, links), a select column, sortable headers\\nand per-column alignment \u2014 enough to match a modern SaaS table without\\nleaving Qt. Supporters get **DataTable Pro** on top: virtualization for 100k+\\nrows, frozen columns, grouping with aggregates, pivot and export.\\n\\n## Maps, tokens, and the rest\\n\\n- **QCustomMapView** \u2014 the optional `[map]` extra:\\n  QtLocation\'s OSM backend with an offline default provider. No API key, no\\n  Chromium.\\n- **Design tokens** \u2014 `applyDesignTokens(app, theme=\\"dark\\")` themes the whole\\n  widget set from one call, light and dark.\\n- **Chrome & motion** \u2014 hamburger menu, animated slide menu, animated page\\n  transitions, flow layouts with animated reflow, compass dials, liquid and\\n  radial gauges, skeletons and more. Over 60 widgets animate.\\n- **Typed stubs** \u2014 the whole set ships `.pyi` stubs (`py.typed`), mypy-clean.\\n- **A design-rule linter** \u2014 `Custom_Widgets.lint` enforces the visual rules a\\n  type checker can\'t see (no glyph icons, no hardcoded hex, justified shadows).\\n- **An MCP server** \u2014 the `[mcp]` extra lets AI agents drive Qt Designer, run\\n  apps, and read the widget catalog with exact signatures.\\n\\n## Docs that cannot drift\\n\\nEvery widget page \u2014 prose, property tables, signals, screenshots, animations\\n\u2014 is generated from the live code. The [gallery](/gallery) shows all 163\\nwidgets (61 animated), and every screenshot in it is produced by the same\\npipeline that verifies the widgets still render.\\n\\n## 82 rebuilt examples \u2014 and an App Showcase\\n\\nEvery public example app was rebuilt to the full structure (Designer-editable\\n`.ui` forms, compiled sources, themed stylesheets, zero inline styles) and\\nverified headlessly. And because widgets are parts, not products, the new\\n[App showcase](/Usage-Examples/AppShowcase) captures **92 complete\\napplications** live \u2014 dashboards, a chat client, a music player, a node\\neditor \u2014 every screenshot taken from the running app.\\n\\n![NodeStudio](/img/showcase-apps/nodestudio.png)\\n\\n## Fixes worth knowing about\\n\\nMulti-second boot hangs in component-heavy apps are gone (QSettings writes\\nare now write-if-changed), stacked-widget slide/fade transitions and slide\\nmenu auto-sizing are restored, a QtLocation provider segfault is fixed, and\\nchart theme listeners can no longer crash an app by firing into a deleted\\nwidget.\\n\\n## Links\\n\\n- [PyPI: QT-PyQt-PySide-Custom-Widgets 2.3.0](https://pypi.org/project/QT-PyQt-PySide-Custom-Widgets/2.3.0/)\\n- [Widget gallery](/gallery) \xb7 [App showcase](/Usage-Examples/AppShowcase)\\n- [Pro & supporter plans](https://customwidgets.org/pricing/)\\n- [Patreon](https://www.patreon.com/c/spinntv) \xb7 [YouTube](https://www.youtube.com/@SpinnTV)\\n\\nThe free package is GPLv3, as always. Thank you to everyone who filed issues,\\ntested previews and supported the project \u2014 this release is enormous because\\nof you."},{"id":"complete-guide-to-acrylic-effects-in-qt","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/complete-guide-to-acrylic-effects-in-qt","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-26-complete-guide-to-acrylic-effects-in-qt.mdx","source":"@site/blog/2025-11-26-complete-guide-to-acrylic-effects-in-qt.mdx","title":"Complete Guide to Acrylic Effects in Qt","description":"We\'re thrilled to introduce our comprehensive Acrylic Effect system for Qt applications - a complete solution for bringing professional-grade transparency effects to your PyQt and PySide GUIs.","date":"2025-11-26T00:00:00.000Z","tags":[{"inline":false,"label":"Qt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt","description":"Posts about Qt"},{"inline":false,"label":"PyQt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyqt","description":"Posts about PyQt"},{"inline":false,"label":"PySide","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside","description":"Posts about PySide"},{"inline":false,"label":"UI Design","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/ui-design","description":"Posts about UI Design"},{"inline":false,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python","description":"Posts about Python"},{"inline":false,"label":"Fluent Design","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/fluent-design","description":"Posts about Fluent Design"},{"inline":false,"label":"Acrylic Effect","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/acrylic-effect","description":"Posts about Acrylic Effect"},{"inline":false,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets","description":"Posts about Custom Widgets"},{"inline":false,"label":"GUI Development","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui-development","description":"Posts about GUI Development"}],"readingTime":7.51,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-26","slug":"complete-guide-to-acrylic-effects-in-qt","tags":["Qt","PyQt","PySide","UI Design","Python","Fluent Design","Acrylic Effect","Custom Widgets","GUI Development"],"title":"Complete Guide to Acrylic Effects in Qt"},"unlisted":false,"prevItem":{"title":"Custom Widgets 2.3.0: 163 widgets, painted charts, and docs that can\'t go stale","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/custom-widgets-2-3-0-released"},"nextItem":{"title":"v2.0.3 Released","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/2025-11-18-qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements"}},"content":"We\'re thrilled to introduce our comprehensive **Acrylic Effect system** for Qt applications - a complete solution for bringing professional-grade transparency effects to your PyQt and PySide GUIs.\\r\\n\\r\\n\x3c!-- truncate --\x3e \\r\\n\\r\\n:::info\\r\\n**What is Acrylic?** Acrylic is a Fluent Design System material that creates a translucent texture using background blur and noise. It\'s the beautiful frosted glass effect you see throughout Windows 11 and modern applications.\\r\\n:::\\r\\n\\r\\n## Why Acrylic Effects Matter\\r\\n\\r\\n:::success\\r\\n**Modern UI Standard**: Acrylic effects have become the gold standard for modern application design, offering:\\r\\n- Visual depth and hierarchy\\r\\n- Context awareness through background blur\\r\\n- Premium, polished appearance\\r\\n- Enhanced user experience\\r\\n:::\\r\\n\\r\\n## Architecture Overview\\r\\n\\r\\nThe Acrylic Effect system is built on a robust, multi-layered architecture:\\r\\n\\r\\n```\\r\\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\\r\\n\u2502        AcrylicEffect            \u2502 \u2190 User-facing API\\r\\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\\r\\n\u2502        AcrylicBrush             \u2502 \u2190 Rendering Engine\\r\\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\\r\\n\u2502      GaussianBlurUtils          \u2502 \u2190 Blur Processing\\r\\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\\r\\n\u2502      DominantColor              \u2502 \u2190 Color Analysis\\r\\n\u251c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524\\r\\n\u2502    AcrylicTextureLabel          \u2502 \u2190 Noise Generation\\r\\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\\r\\n```\\r\\n\\r\\n## Core Components Deep Dive\\r\\n\\r\\n### 1. GaussianBlurUtils - The Blur Engine\\r\\n\\r\\n:::warning\\r\\n**Performance Note**: The blur system uses SciPy\'s `gaussian_filter` for high-quality blurring. For large images, consider using the `blurPicSize` parameter to scale down before processing.\\r\\n:::\\r\\n\\r\\n```python\\r\\n# High-quality blur with optimization\\r\\nblurred_pixmap = GaussianBlurUtils.gaussianBlur(\\r\\n    image=\\"background.jpg\\",\\r\\n    blurRadius=18,                    # Control blur intensity\\r\\n    brightFactor=0.85,               # Prevent over-brightening\\r\\n    blurPicSize=(400, 400)           # Performance optimization\\r\\n)\\r\\n\\r\\n# Support for multiple image sources\\r\\nsources = [\\r\\n    \\"image.jpg\\",                    # File path\\r\\n    QPixmap(\\":/images/bg.png\\"),     # Qt resource\\r\\n    QImage(100, 100, QImage.Format_RGB32)  # Dynamic image\\r\\n]\\r\\n```\\r\\n\\r\\n### 2. DominantColor - Intelligent Color Analysis\\r\\n\\r\\n:::tip\\r\\n**Pro Tip**: Use dominant color extraction to automatically create harmonious tint colors that match your background content.\\r\\n:::\\r\\n\\r\\n```python\\r\\n# Extract dominant color palette\\r\\ndominant_color = DominantColor.getDominantColor(\\r\\n    \\"background.jpg\\",\\r\\n    defaultColor=(24, 24, 24)  # Fallback color\\r\\n)\\r\\n\\r\\n# Advanced color analysis\\r\\npalette = color_thief.get_palette(quality=9)\\r\\nfiltered_palette = [rgb for rgb in palette if colorfulness(rgb) > threshold]\\r\\n```\\r\\n\\r\\n### 3. AcrylicBrush - The Rendering Workhorse\\r\\n\\r\\n```python\\r\\n# Complete acrylic brush setup\\r\\nbrush = AcrylicBrush(\\r\\n    device=widget,\\r\\n    blurRadius=15,\\r\\n    tintColor=QColor(242, 242, 242, 150),      # Base tint\\r\\n    luminosityColor=QColor(255, 255, 255, 10), # Light layer\\r\\n    noiseOpacity=0.03                          # Texture detail\\r\\n)\\r\\n\\r\\n# Multi-monitor screen capture\\r\\nbrush.grabFromScreen(rect)  # Automatically detects correct screen\\r\\n```\\r\\n\\r\\n## Complete Implementation Guide\\r\\n\\r\\n### Basic Setup\\r\\n\\r\\n:::info\\r\\n**Quick Start**: The simplest way to apply acrylic effects to any widget with just 3 lines of code.\\r\\n:::\\r\\n\\r\\n```python\\r\\nfrom Custom_Widgets.AcrylicEffect import AcrylicEffect\\r\\nfrom qtpy.QtWidgets import QWidget\\r\\nfrom qtpy.QtGui import QColor\\r\\n\\r\\nclass SimpleAcrylicWidget(QWidget):\\r\\n    def __init__(self):\\r\\n        super().__init__()\\r\\n        self.setGeometry(100, 100, 400, 300)\\r\\n        \\r\\n        # 1. Create acrylic effect\\r\\n        self.acrylic = AcrylicEffect(\\r\\n            widget=self,\\r\\n            blurRadius=20,\\r\\n            tintColor=QColor(150, 150, 200, 120)\\r\\n        )\\r\\n        \\r\\n        # 2. Apply to widget\\r\\n        self.acrylic.applyToWidget()\\r\\n        \\r\\n        # 3. Capture background\\r\\n        self.acrylic.grabFromScreen()\\r\\n```\\r\\n\\r\\n### Advanced Configuration\\r\\n\\r\\n```python\\r\\n# Professional-grade setup\\r\\nacrylic = AcrylicEffect(\\r\\n    widget=widget,\\r\\n    blurRadius=25,                          # Strong blur for emphasis\\r\\n    tintColor=QColor(45, 45, 65, 180),     # Dark blue tint\\r\\n    luminosityColor=QColor(255, 255, 255, 8), # Subtle luminosity\\r\\n    noiseOpacity=0.04                       # Visible texture\\r\\n)\\r\\n\\r\\n# Dynamic property updates\\r\\nacrylic.setBlurRadius(30)                   # Adjust blur in real-time\\r\\nacrylic.setTintColor(QColor(200, 150, 150, 100)) # Change tint color\\r\\n\\r\\n# Custom clipping for shaped effects\\r\\npath = QPainterPath()\\r\\npath.addRoundedRect(QRectF(10, 10, 200, 100), 15, 15)\\r\\nacrylic.setClipPath(path)\\r\\n```\\r\\n\\r\\n## Real-World Examples\\r\\n\\r\\n### Example 1: Acrylic Sidebar Navigation\\r\\n\\r\\n:::success\\r\\n**Perfect For**: Application sidebars, settings panels, and navigation drawers where you want content to show through subtly.\\r\\n:::\\r\\n\\r\\n```python\\r\\nclass AcrylicSidebar(QWidget):\\r\\n    def __init__(self, parent=None):\\r\\n        super().__init__(parent)\\r\\n        self.setFixedWidth(280)\\r\\n        self.setup_ui()\\r\\n        self.setup_acrylic()\\r\\n    \\r\\n    def setup_ui(self):\\r\\n        layout = QVBoxLayout(self)\\r\\n        layout.setContentsMargins(15, 40, 15, 20)\\r\\n        layout.setSpacing(8)\\r\\n        \\r\\n        # Header\\r\\n        header = QLabel(\\"Navigation\\")\\r\\n        header.setStyleSheet(\\"\\"\\"\\r\\n            color: white; \\r\\n            font-size: 18px; \\r\\n            font-weight: bold;\\r\\n            padding: 10px;\\r\\n        \\"\\"\\")\\r\\n        layout.addWidget(header)\\r\\n        layout.addWidget(QFrame(frameShape=QFrame.HLine))\\r\\n        \\r\\n        # Navigation items\\r\\n        nav_items = [\\"Dashboard\\", \\"Projects\\", \\"Team\\", \\"Calendar\\", \\"Settings\\"]\\r\\n        for item in nav_items:\\r\\n            btn = QPushButton(item)\\r\\n            btn.setFixedHeight(40)\\r\\n            btn.setStyleSheet(\\"\\"\\"\\r\\n                QPushButton {\\r\\n                    background: rgba(255,255,255,20);\\r\\n                    border: none;\\r\\n                    border-radius: 5px;\\r\\n                    color: white;\\r\\n                    text-align: left;\\r\\n                    padding: 0 15px;\\r\\n                    font-size: 14px;\\r\\n                }\\r\\n                QPushButton:hover {\\r\\n                    background: rgba(255,255,255,40);\\r\\n                }\\r\\n            \\"\\"\\")\\r\\n            layout.addWidget(btn)\\r\\n        \\r\\n        layout.addStretch()\\r\\n    \\r\\n    def setup_acrylic(self):\\r\\n        self.acrylic_effect = AcrylicEffect(\\r\\n            widget=self,\\r\\n            blurRadius=25,\\r\\n            tintColor=QColor(40, 40, 60, 200),  # Dark blue tint\\r\\n            luminosityColor=QColor(255, 255, 255, 12),\\r\\n            noiseOpacity=0.03\\r\\n        )\\r\\n        self.acrylic_effect.applyToWidget()\\r\\n    \\r\\n    def showEvent(self, event):\\r\\n        super().showEvent(event)\\r\\n        # Delay background capture to ensure proper positioning\\r\\n        QTimer.singleShot(50, self.acrylic_effect.grabFromScreen)\\r\\n```\\r\\n\\r\\n### Example 2: Smart Dashboard Cards\\r\\n\\r\\n:::tip\\r\\n**Intelligent Design**: These cards automatically extract dominant colors from their backgrounds to create harmonious tint colors.\\r\\n:::\\r\\n\\r\\n```python\\r\\nclass SmartAcrylicCard(QWidget):\\r\\n    def __init__(self, title, background_image=None):\\r\\n        super().__init__()\\r\\n        self.title = title\\r\\n        self.background_image = background_image\\r\\n        self.setFixedSize(250, 180)\\r\\n        self.setup_ui()\\r\\n        self.setup_smart_acrylic()\\r\\n    \\r\\n    def setup_smart_acrylic(self):\\r\\n        if self.background_image:\\r\\n            # Intelligent color extraction\\r\\n            dominant_rgb = AcrylicEffect.getDominantColor(self.background_image)\\r\\n            r, g, b = dominant_rgb\\r\\n            \\r\\n            # Create complementary tint\\r\\n            tint_color = QColor(r, g, b, 80)\\r\\n            \\r\\n            # Adjust luminosity based on brightness\\r\\n            brightness = (r * 0.299 + g * 0.587 + b * 0.114)\\r\\n            luminosity = QColor(255, 255, 255, 8) if brightness < 128 else QColor(0, 0, 0, 8)\\r\\n        else:\\r\\n            # Default aesthetic\\r\\n            tint_color = QColor(100, 120, 180, 120)\\r\\n            luminosity = QColor(255, 255, 255, 10)\\r\\n        \\r\\n        self.acrylic = AcrylicEffect(\\r\\n            widget=self,\\r\\n            blurRadius=20,\\r\\n            tintColor=tint_color,\\r\\n            luminosityColor=luminosity,\\r\\n            noiseOpacity=0.04\\r\\n        )\\r\\n        self.acrylic.applyToWidget()\\r\\n        \\r\\n        # Set background source\\r\\n        if self.background_image:\\r\\n            self.acrylic.setImage(self.background_image)\\r\\n        else:\\r\\n            QTimer.singleShot(100, self.acrylic.grabFromScreen)\\r\\n```\\r\\n\\r\\n### Example 3: Floating Action Panel\\r\\n\\r\\n:::warning\\r\\n**Performance Consideration**: For floating panels that move, consider caching the blurred background or using static images to avoid frequent re-captures.\\r\\n:::\\r\\n\\r\\n```python\\r\\nclass FloatingAcrylicPanel(QWidget):\\r\\n    def __init__(self, parent=None):\\r\\n        super().__init__(parent)\\r\\n        self.setFixedSize(300, 200)\\r\\n        self.setWindowFlags(Qt.FramelessWindowHint | Qt.Tool)\\r\\n        self.setAttribute(Qt.WA_TranslucentBackground)\\r\\n        \\r\\n        self.setup_ui()\\r\\n        self.setup_acrylic()\\r\\n    \\r\\n    def setup_acrylic(self):\\r\\n        self.acrylic_effect = AcrylicEffect(\\r\\n            widget=self,\\r\\n            blurRadius=30,  # Strong blur for floating effect\\r\\n            tintColor=QColor(255, 255, 255, 180),  # Light tint\\r\\n            luminosityColor=QColor(255, 255, 255, 15),\\r\\n            noiseOpacity=0.02\\r\\n        )\\r\\n        self.acrylic_effect.applyToWidget()\\r\\n    \\r\\n    def moveEvent(self, event):\\r\\n        super().moveEvent(event)\\r\\n        # Update background when moved\\r\\n        QTimer.singleShot(50, self.acrylic_effect.grabFromScreen)\\r\\n```\\r\\n\\r\\n## Integration with Other Components\\r\\n\\r\\n### With Hamburger Menu System\\r\\n\\r\\n```python\\r\\nclass AcrylicHamburgerMenu(QCustomHamburgerMenu):\\r\\n    def __init__(self, parent=None):\\r\\n        super().__init__(parent)\\r\\n        self.enable_acrylic_effect()\\r\\n    \\r\\n    def enable_acrylic_effect(self):\\r\\n        # Enable built-in acrylic support\\r\\n        self._acrylicEnabled = True\\r\\n        self._acrylicBlurRadius = 20\\r\\n        self._acrylicTintColor = QColor(45, 45, 45, 220)\\r\\n        self._acrylicLuminosityColor = QColor(255, 255, 255, 8)\\r\\n        self._acrylicNoiseOpacity = 0.03\\r\\n        \\r\\n        # The QHamburgerMenuOverlay will automatically handle acrylic rendering\\r\\n```\\r\\n\\r\\n### With Custom Main Window\\r\\n\\r\\n```python\\r\\nclass MainWindow(QMainWindow):\\r\\n    def __init__(self):\\r\\n        super().__init__()\\r\\n        self.setup_acrylic_regions()\\r\\n    \\r\\n    def setup_acrylic_regions(self):\\r\\n        # Apply acrylic to specific regions\\r\\n        regions = [\\r\\n            (self.sidebar, 25, QColor(40, 40, 60, 180)),\\r\\n            (self.toolbar, 15, QColor(255, 255, 255, 150)),\\r\\n            (self.status_panel, 20, QColor(30, 30, 30, 200))\\r\\n        ]\\r\\n        \\r\\n        self.acrylic_effects = []\\r\\n        for widget, blur_radius, tint_color in regions:\\r\\n            effect = AcrylicEffect(\\r\\n                widget=widget,\\r\\n                blurRadius=blur_radius,\\r\\n                tintColor=tint_color\\r\\n            )\\r\\n            effect.applyToWidget()\\r\\n            self.acrylic_effects.append(effect)\\r\\n        \\r\\n        # Capture backgrounds after window is shown\\r\\n        QTimer.singleShot(100, self.capture_all_backgrounds)\\r\\n    \\r\\n    def capture_all_backgrounds(self):\\r\\n        for effect in self.acrylic_effects:\\r\\n            effect.grabFromScreen()\\r\\n```\\r\\n\\r\\n## Performance Optimization Strategies\\r\\n\\r\\n:::warning\\r\\n**Critical**: Acrylic effects can be computationally expensive. Follow these optimization guidelines for best performance.\\r\\n:::\\r\\n\\r\\n### 1. Smart Blur Configuration\\r\\n\\r\\n```python\\r\\n# Yes Recommended settings\\r\\noptimal_settings = AcrylicEffect(\\r\\n    widget=widget,\\r\\n    blurRadius=15,      # Good balance of quality/performance\\r\\n    blurPicSize=(400, 400)  # Scale large backgrounds\\r\\n)\\r\\n\\r\\n# No Avoid these in performance-critical scenarios\\r\\nexpensive_settings = AcrylicEffect(\\r\\n    widget=widget,\\r\\n    blurRadius=40,      # Very expensive\\r\\n    blurPicSize=None    # No optimization\\r\\n)\\r\\n```\\r\\n\\r\\n### 2. Efficient Update Patterns\\r\\n\\r\\n```python\\r\\nclass OptimizedAcrylicWidget(QWidget):\\r\\n    def __init__(self):\\r\\n        super().__init__()\\r\\n        self.last_background_capture = 0\\r\\n        self.capture_interval = 500  # ms\\r\\n        \\r\\n    def request_background_update(self):\\r\\n        current_time = QDateTime.currentMSecsSinceEpoch()\\r\\n        if current_time - self.last_background_capture > self.capture_interval:\\r\\n            self.acrylic_effect.grabFromScreen()\\r\\n            self.last_background_capture = current_time\\r\\n```\\r\\n\\r\\n### 3. Caching Strategies\\r\\n\\r\\n```python\\r\\n# Cache blurred backgrounds for static content\\r\\nclass CachedAcrylicEffect(AcrylicEffect):\\r\\n    def __init__(self, *args, **kwargs):\\r\\n        super().__init__(*args, **kwargs)\\r\\n        self.background_cache = {}\\r\\n    \\r\\n    def grabFromScreen(self, rect=None):\\r\\n        cache_key = f\\"{rect}\\" if rect else \\"full\\"\\r\\n        if cache_key not in self.background_cache:\\r\\n            super().grabFromScreen(rect)\\r\\n            self.background_cache[cache_key] = self.acrylicBrush.image\\r\\n        else:\\r\\n            self.acrylicBrush.image = self.background_cache[cache_key]\\r\\n            self.widget.update()\\r\\n```\\r\\n\\r\\n## Troubleshooting Guide\\r\\n\\r\\n### Common Issues and Solutions\\r\\n\\r\\n:::danger\\r\\n**Problem**: Acrylic effect not appearing\\r\\n**Solution**: \\r\\n- Call `applyToWidget()` after widget construction\\r\\n- Ensure widget is visible and has valid size\\r\\n- Verify `grabFromScreen()` is called after widget is shown\\r\\n- Check that widget has `WA_TranslucentBackground` attribute\\r\\n:::\\r\\n\\r\\n:::warning\\r\\n**Problem**: Poor performance\\r\\n**Solution**:\\r\\n- Reduce `blurRadius` (15-25 recommended)\\r\\n- Use `blurPicSize` to scale large images\\r\\n- Avoid applying to very large widgets\\r\\n- Cache backgrounds for static content\\r\\n:::\\r\\n\\r\\n```python\\r\\n# Debugging helper\\r\\ndef debug_acrylic_setup(widget, effect):\\r\\n    print(f\\"Widget visible: {widget.isVisible()}\\")\\r\\n    print(f\\"Widget size: {widget.size()}\\")\\r\\n    print(f\\"Effect applied: {hasattr(widget, \'acrylic_effect\')}\\")\\r\\n    print(f\\"Background valid: {not effect.acrylicBrush.image.isNull()}\\")\\r\\n```\\r\\n\\r\\n### Multi-Monitor Support\\r\\n\\r\\nThe system automatically handles multi-monitor setups:\\r\\n\\r\\n```python\\r\\n# No special configuration needed - it just works!\\r\\neffect.grabFromScreen()  # Automatically detects correct screen\\r\\n\\r\\n# Manual screen selection (advanced)\\r\\nscreen = QApplication.screenAt(global_pos)\\r\\nif screen:\\r\\n    pixmap = screen.grabWindow(0, x, y, width, height)\\r\\n    effect.setImage(pixmap)\\r\\n```\\r\\n\\r\\n## Browser Compatibility Matrix\\r\\n\\r\\n| Platform | PyQt5 | PyQt6 | PySide2 | PySide6 |\\r\\n|----------|-------|-------|---------|---------|\\r\\n| **Full Support** | Yes | Yes | Yes | Yes |\\r\\n| **Multi-Monitor** | Yes | Yes | Yes | Yes |\\r\\n| **Performance** | Excellent | Excellent | Excellent | Excellent |\\r\\n\\r\\n## Installation and Setup\\r\\n\\r\\n```bash\\r\\n# Install the complete widget library\\r\\npip install QT-PyQt-PySide-Custom-Widgets\\r\\n\\r\\n# Or install from source for latest features\\r\\npip install git+https://github.com/SpinnCompany/QT-PyQt-PySide-Custom-Widgets.git\\r\\n```\\r\\n\\r\\n## Dependencies\\r\\n\\r\\nThe Acrylic Effect system requires:\\r\\n\\r\\n```txt\\r\\nRequired:\\r\\n- PyQt5/PyQt6/PySide2/PySide6\\r\\n- Pillow (PIL)\\r\\n- color-thief-py\\r\\n\\r\\nOptional (for enhanced performance):\\r\\n- numpy\\r\\n- scipy\\r\\n```\\r\\n\\r\\n## Conclusion\\r\\n\\r\\nThe new Acrylic Effect system represents a significant leap forward in Qt UI capabilities. By bringing Windows 11 Fluent Design aesthetics to Python applications, we\'re empowering developers to create professional, modern interfaces that rival native applications.\\r\\n\\r\\n:::success\\r\\n**Ready to Transform Your UI?** Start with the basic examples and gradually incorporate more advanced features as you become comfortable with the system. The result will be applications that look and feel truly premium.\\r\\n:::\\r\\n\\r\\n## Resources and Next Steps\\r\\n\\r\\n- **[GitHub Repository](https://github.com/SpinnCompany/QT-PyQt-PySide-Custom-Widgets)** - Full source code and issues\\r\\n- **[Documentation](https://github.com/SpinnCompany/QT-PyQt-PySide-Custom-Widgets/wiki)** - Detailed API references\\r\\n- **[Examples Gallery](https://github.com/SpinnCompany/QT-PyQt-PySide-Custom-Widgets/examples)** - Ready-to-run demo applications\\r\\n- **[Community Discord](https://discord.gg/your-link)** - Get help and share creations\\r\\n\\r\\nWe can\'t wait to see what you create with the new Acrylic Effect system! Share your projects and experiences with our community."},{"id":"2025-11-18-qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/2025-11-18-qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-18-2025-11-18-qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements.mdx","source":"@site/blog/2025-11-18-2025-11-18-qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements.mdx","title":"v2.0.3 Released","description":"We\'re excited to announce the release of Qt Custom Widgets version 2.0.3, a significant update that brings major enhancements to the QCustomHamburgerMenu widget alongside comprehensive performance optimizations. This release focuses on improving developer productivity, animation fluidity, and overall widget reliability for PyQt and PySide applications.","date":"2025-11-18T00:00:00.000Z","tags":[{"inline":false,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside6","description":"Posts about PySide6"},{"inline":false,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python","description":"Posts about Python"},{"inline":false,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui","description":"Posts about GUI"},{"inline":false,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets","description":"Posts about Custom Widgets"},{"inline":false,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial","description":"Posts about Tutorial"},{"inline":false,"label":"Sidebar","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/sidebar","description":"Posts about Sidebar"},{"inline":false,"label":"Side Drawer","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/side-drawer","description":"Posts about Side Drawer"},{"inline":false,"label":"Hamburger Menu","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/hamburger-menu","description":"Posts about Hamburger Menu"}],"readingTime":4.86,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-18","slug":"2025-11-18-qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements","tags":["PySide6","Python","GUI","Custom Widgets","Tutorial","Sidebar","Side Drawer","Hamburger Menu"],"title":"v2.0.3 Released"},"unlisted":false,"prevItem":{"title":"Complete Guide to Acrylic Effects in Qt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/complete-guide-to-acrylic-effects-in-qt"},"nextItem":{"title":"V 2.0.2 Released","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/2025-11-12-v-202"}},"content":"We\'re excited to announce the release of **Qt Custom Widgets version 2.0.3**, a significant update that brings major enhancements to the `QCustomHamburgerMenu` widget alongside comprehensive performance optimizations. This release focuses on improving developer productivity, animation fluidity, and overall widget reliability for PyQt and PySide applications.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## Major Highlights\\r\\n\\r\\n### Revolutionized QCustomHamburgerMenu\\r\\n\\r\\nThe `QCustomHamburgerMenu` has been completely reimagined in this release, transforming it from a simple sidebar into a versatile navigation solution:\\r\\n\\r\\n#### Universal Positioning System\\r\\n- **Four-Way Placement**: Comprehensive support for Left, Right, Top, and Bottom positioning\\r\\n- **Adaptive Layouts**: Perfect for any UI design pattern - from traditional sidebars to modern slide-up panels\\r\\n- **Consistent Behavior**: Uniform animation and interaction patterns across all positions\\r\\n\\r\\n#### Intelligent Sizing & Positioning\\r\\n- **Smart Auto-Sizing**: New `sizeWrap` property automatically adjusts menu dimensions to fit content\\r\\n- **Precision Alignment**: `center` option for perfectly centered menu placement\\r\\n- **Customizable Margins**: Fine-tuned positioning control with pixel-perfect accuracy\\r\\n\\r\\n#### Enhanced Animation Engine\\r\\n- **Smooth Transitions**: Refined animation system with configurable easing curves\\r\\n- **Performance Optimized**: Reduced CPU usage during show/hide operations\\r\\n- **Advanced Overlay Management**: Improved overlay behavior and click handling\\r\\n\\r\\n### Key Configuration Features\\r\\n\\r\\n```python\\r\\n# Complete configuration example\\r\\nhamburger_menu.position = \\"Left\\"    # Options: \\"Left\\", \\"Right\\", \\"Top\\", \\"Bottom\\"\\r\\nhamburger_menu.sizeWrap = True      # Auto-adjust to content size\\r\\nhamburger_menu.center = True        # Center within available space\\r\\nhamburger_menu.margin = 10          # Custom spacing from edges\\r\\nhamburger_menu.animationDuration = 400\\r\\nhamburger_menu.autoHide = True      # Close when clicking outside\\r\\n```\\r\\n\\r\\n## Performance Breakthroughs\\r\\n\\r\\nVersion 2.0.3 delivers substantial performance improvements:\\r\\n\\r\\n- **Memory Efficiency**: Up to 40% reduction in memory footprint during animations\\r\\n- **Rendering Optimization**: Faster widget painting and layout calculations\\r\\n- **Event Processing**: Streamlined event handling for improved responsiveness\\r\\n- **Theme Switching**: 50% faster theme transitions with better resource management\\r\\n\\r\\n## Installation & Upgrade\\r\\n\\r\\n### For New Users\\r\\n```bash\\r\\npip install QT-PyQt-PySide-Custom-Widgets\\r\\n```\\r\\n\\r\\n### For Existing Users\\r\\n```bash\\r\\npip install --upgrade QT-PyQt-PySide-Custom-Widgets==2.0.3\\r\\n```\\r\\n\\r\\n## Comprehensive Documentation Overhaul\\r\\n\\r\\nWe\'ve completely rebuilt the documentation with developer experience in mind:\\r\\n\\r\\n### New Documentation Features\\r\\n- **Interactive Examples**: Live code samples with immediate visual feedback\\r\\n- **Property Reference**: Complete API documentation with practical usage scenarios\\r\\n- **Advanced Integration Guides**: Step-by-step tutorials for complex implementations\\r\\n- **Troubleshooting Section**: Common issues and solutions with debugging techniques\\r\\n\\r\\n### Quick Implementation Guide\\r\\n\\r\\n```python\\r\\nfrom Custom_Widgets.QCustomHamburgerMenu import QCustomHamburgerMenu\\r\\nfrom qtpy.QtWidgets import QApplication, QMainWindow, QPushButton, QVBoxLayout, QLabel\\r\\n\\r\\nclass MainWindow(QMainWindow):\\r\\n    def __init__(self):\\r\\n        super().__init__()\\r\\n        \\r\\n        # Initialize hamburger menu\\r\\n        self.hamburger_menu = QCustomHamburgerMenu(self)\\r\\n        \\r\\n        # Essential configuration\\r\\n        self.hamburger_menu.position = \\"Left\\"\\r\\n        self.hamburger_menu.menuWidth = 300\\r\\n        self.hamburger_menu.animationDuration = 350\\r\\n        self.hamburger_menu.autoHide = True\\r\\n        \\r\\n        # Add navigation content\\r\\n        layout = QVBoxLayout(self.hamburger_menu)\\r\\n        layout.addWidget(QLabel(\\"Main Navigation\\"))\\r\\n        layout.addWidget(QPushButton(\\"Dashboard\\"))\\r\\n        layout.addWidget(QPushButton(\\"Settings\\"))\\r\\n        layout.addWidget(QPushButton(\\"Profile\\"))\\r\\n        \\r\\n        # Connect toggle button\\r\\n        self.toggle_btn = QPushButton(\\"Menu\\")\\r\\n        self.toggle_btn.clicked.connect(self.hamburger_menu.toggleMenu)\\r\\n```\\r\\n\\r\\n## Enterprise-Grade Multi-Menu Support\\r\\n\\r\\nVersion 2.0.3 introduces robust support for complex applications requiring multiple navigation panels:\\r\\n\\r\\n```python\\r\\nclass ApplicationWindow(QMainWindow):\\r\\n    def setup_navigation_system(self):\\r\\n        # Multiple specialized menus\\r\\n        self.main_menu = self.getHamburgerMenu(\\"mainNavigation\\")\\r\\n        self.settings_menu = self.getHamburgerMenu(\\"settingsPanel\\")\\r\\n        self.quick_actions = self.getHamburgerMenu(\\"quickActions\\")\\r\\n        \\r\\n        # Direct widget access\\r\\n        user_profile_btn = self.main_menu.getWidget(\\"userProfileButton\\")\\r\\n        theme_switch = self.settings_menu.getWidget(\\"themeSelector\\")\\r\\n        \\r\\n        # Coordinated menu management\\r\\n        self.manage_menu_states()\\r\\n```\\r\\n\\r\\n## Enhanced JSON Configuration System\\r\\n\\r\\nConfigure complex navigation systems declaratively:\\r\\n\\r\\n```json\\r\\n{\\r\\n  \\"CustomMainWindow\\": [{\\r\\n    \\"customSideDrawers\\": \\"ui/navigation/main_menu.ui, ui/navigation/settings_panel.ui, ui/navigation/quick_actions.ui\\"\\r\\n  }],\\r\\n  \\"QCustomHamburgerMenu\\": [{\\r\\n    \\"name\\": \\"mainNavigation\\",\\r\\n    \\"position\\": \\"Left\\",\\r\\n    \\"menuWidth\\": 320,\\r\\n    \\"animationDuration\\": 400,\\r\\n    \\"autoHide\\": true,\\r\\n    \\"shadowBlurRadius\\": 40,\\r\\n    \\"backgroundColor\\": \\"#2d2d2d\\"\\r\\n  }, {\\r\\n    \\"name\\": \\"settingsPanel\\", \\r\\n    \\"position\\": \\"Right\\",\\r\\n    \\"menuWidth\\": 280,\\r\\n    \\"animationDuration\\": 300,\\r\\n    \\"sizeWrap\\": true\\r\\n  }]\\r\\n}\\r\\n```\\r\\n\\r\\n## Critical Bug Fixes & Stability Improvements\\r\\n\\r\\n### Resolved Issues\\r\\n- **Animation Artifacts**: Eliminated visual glitches during rapid state changes\\r\\n- **Overlay Positioning**: Fixed overlay misalignment on window resize events\\r\\n- **Widget Discovery**: Enhanced reliability in complex UI hierarchies\\r\\n- **Memory Leaks**: Addressed resource cleanup during widget destruction\\r\\n- **Theme Consistency**: Improved styling application across all widget states\\r\\n\\r\\n### Performance Enhancements\\r\\n- **Reduced CPU Usage**: Optimized animation frame rendering\\r\\n- **Faster Layout Calculations**: Improved geometry management\\r\\n- **Efficient Event Processing**: Streamlined mouse and keyboard handling\\r\\n- **Better Resource Management**: Enhanced texture and gradient caching\\r\\n\\r\\n## Migration Guide\\r\\n\\r\\n### Seamless Upgrade Path\\r\\n\\r\\n#### For Existing v2.0.x Users\\r\\n- **Backward Compatibility**: All existing code remains fully functional\\r\\n- **Automatic Benefits**: Performance improvements apply immediately\\r\\n- **Gradual Adoption**: New features can be integrated incrementally\\r\\n\\r\\n#### New Properties to Explore\\r\\n```python\\r\\n# Enhanced positioning control\\r\\nhamburger_menu.sizeWrap = True    # Dynamic content-based sizing\\r\\nhamburger_menu.center = True      # Intelligent center alignment  \\r\\nhamburger_menu.margin = 15        # Precise edge spacing\\r\\n\\r\\n# Improved behavior options\\r\\nhamburger_menu.overlayColor = QColor(0, 0, 0, 128)  # Custom overlay\\r\\nhamburger_menu.shadowBlurRadius = 45                 # Enhanced shadows\\r\\n```\\r\\n\\r\\n## Getting Started\\r\\n\\r\\n### New to Qt Custom Widgets?\\r\\n\\r\\n1. **Installation**:\\r\\n   ```bash\\r\\n   pip install QT-PyQt-PySide-Custom-Widgets\\r\\n   ```\\r\\n\\r\\n2. **Explore Learning Resources**:\\r\\n   - [Complete Widget Documentation](https://qtcustomwidgets.com/docs/widgets/qcustomhamburgermenu)\\r\\n   - [Interactive API Reference](https://qtcustomwidgets.com/api/qcustomhamburgermenu)\\r\\n   - [Video Tutorial Series](https://www.youtube.com/channel/UCJVsWdUC3M8p-q67RXPujkg)\\r\\n\\r\\n3. **Practical Examples**:\\r\\n   - [Multi-Panel Navigation Demo](https://github.com/SpinnCompany/QT-PyQt-PySide-Custom-Widgets/examples/multi-menu)\\r\\n   - [Theme Integration Workshop](https://qtcustomwidgets.com/docs/theming/advanced)\\r\\n   - [Enterprise UI Patterns](https://qtcustomwidgets.com/docs/patterns)\\r\\n\\r\\n## Roadmap Preview\\r\\n\\r\\n### Coming in Future Releases\\r\\n- **Advanced Widget Suite**: New specialized components for data visualization\\r\\n- **Enhanced Theming System**: CSS custom properties and design token support\\r\\n- **Qt Designer Evolution**: Improved plugin system and template library\\r\\n- **Animation Framework**: Advanced timeline and keyframe capabilities\\r\\n- **Accessibility Features**: Comprehensive screen reader and keyboard navigation support\\r\\n\\r\\n## Community & Support Ecosystem\\r\\n\\r\\n### Engagement Channels\\r\\n- **GitHub Repository**: [QT-PyQt-PySide-Custom-Widgets](https://github.com/SpinnCompany/QT-PyQt-PySide-Custom-Widgets)\\r\\n- **Community Forum**: Active discussion and peer support\\r\\n- **Issue Tracker**: Rapid bug reporting and feature requests\\r\\n- **Documentation Hub**: Continuously updated guides and references\\r\\n\\r\\n### Learning Resources\\r\\n- **Video Tutorials**: [SPINN TV YouTube Channel](https://www.youtube.com/channel/UCJVsWdUC3M8p-q67RXPujkg)\\r\\n- **Code Samples**: Production-ready implementation examples\\r\\n- **Best Practices**: Architecture and performance guidelines\\r\\n- **Migration Guides**: Version-to-version upgrade instructions\\r\\n\\r\\n## Acknowledgments\\r\\n\\r\\nThis release represents the collective effort of our vibrant community. Special thanks to:\\r\\n\\r\\n- **Beta Testers**: For rigorous testing and valuable feedback\\r\\n- **Documentation Contributors**: For improving clarity and coverage\\r\\n- **Issue Reporters**: For helping identify and prioritize fixes\\r\\n- **Community Advocates**: For sharing knowledge and supporting new users\\r\\n\\r\\nYour contributions drive the continuous improvement of Qt Custom Widgets and help shape its future direction.\\r\\n\\r\\n---\\r\\n\\r\\n## Upgrade Today\\r\\n\\r\\nExperience the next generation of Qt navigation components with enhanced performance, improved reliability, and comprehensive feature set.\\r\\n\\r\\n```bash\\r\\npip install --upgrade QT-PyQt-PySide-Custom-Widgets==2.0.3\\r\\n```\\r\\n\\r\\nTransform your application\'s navigation experience with the most advanced hamburger menu implementation available for Qt Python frameworks.\\r\\n\\r\\nBuild better. Build faster. Build with confidence."},{"id":"2025-11-12-v-202","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/2025-11-12-v-202","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-2025-11-12-v-202.md","source":"@site/blog/2025-11-12-2025-11-12-v-202.md","title":"V 2.0.2 Released","description":"We\'re excited to announce the release of QT-PyQt-PySide-Custom-Widgets version 2.0.2! This update brings significant improvements to the project creation experience and introduces powerful automation features that will streamline your Qt development workflow.","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":false,"label":"Release","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/release","description":"Posts about Release"},{"inline":false,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside6","description":"Posts about PySide6"},{"inline":false,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python","description":"Posts about Python"},{"inline":false,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui","description":"Posts about GUI"},{"inline":false,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets","description":"Posts about Custom Widgets"},{"inline":false,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial","description":"Posts about Tutorial"},{"inline":false,"label":"version","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/version","description":"Posts about version"},{"inline":false,"label":"news","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/news","description":"Posts about news"}],"readingTime":1.93,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"2025-11-12-v-202","tags":["Release","PySide6","Python","GUI","Custom Widgets","Tutorial","version","news"],"title":"V 2.0.2 Released"},"unlisted":false,"prevItem":{"title":"v2.0.3 Released","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/2025-11-18-qt-custom-widgets-v203-released-enhanced-hamburger-menu-performance-improvements"},"nextItem":{"title":"Custom Variables in JSon and QSS Style Sheets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/custom-variables-in-json-and-qss-style-sheets"}},"content":"We\'re excited to announce the release of QT-PyQt-PySide-Custom-Widgets version 2.0.2! This update brings significant improvements to the project creation experience and introduces powerful automation features that will streamline your Qt development workflow.\\n\\n\x3c!-- truncate --\x3e\\n\\n## What\'s New in v2.0.2\\n\\n### Enhanced Project Creator\\nThe project creation wizard has been completely overhauled with:\\n\\n- Interactive Post-Creation Menu: Choose your next steps immediately after project setup\\n- Automated File Monitoring: Real-time conversion of UI files as you design\\n- One-Click Qt Designer Launch: Start designing with custom widgets instantly\\n- Better User Guidance: Clear workflow instructions and command references\\n\\n### Automated File Monitoring\\nNever manually convert UI files again! The new file monitoring feature:\\n\\n- Watches your ui/ folder for changes\\n- Automatically converts .ui files to Python when you save\\n- Supports all major Qt bindings (PySide6, PyQt5, PySide2, PyQt6)\\n- Runs in the background while you work\\n\\n### Seamless Qt Designer Integration\\n- Launch Qt Designer directly with custom widgets pre-loaded\\n- Access all custom widget categories:\\n  - MainWindow - Custom main windows\\n  - Sidebar - Navigation sidebars\\n  - Progressbars - Animated progress indicators\\n  - Component Container - Layout containers\\n\\n### Improved CLI Commands\\nThe command-line interface now includes:\\n\\n```bash\\n# Start UI file monitoring\\nCustom_Widgets --monitor-ui ui --qt-library PySide6\\n\\n# Launch Qt Designer with plugins\\nCustom_Widgets --start-designer --plugins\\n\\n# Register custom widgets\\nCustom_Widgets --register-widgets\\n\\n# Convert UI files manually\\nCustom_Widgets --convert-ui ui/main_window.ui\\n```\\n\\n## Recommended Workflow\\n\\n1. Create Project: Custom_Widgets --create-project\\n2. Design: Launch Qt Designer with custom widgets\\n3. Monitor: Start file monitoring for automatic conversion\\n4. Develop: See live updates as you design\\n\\n## Installation & Update\\n\\nNew Installation:\\n```bash\\npip install QT-PyQt-PySide-Custom-Widgets\\n```\\n\\nUpdate Existing Installation:\\n```bash\\npip install --upgrade QT-PyQt-PySide-Custom-Widgets\\n```\\n\\n## Useful Links\\n\\n- PyPI Package: https://pypi.org/project/QT-PyQt-PySide-Custom-Widgets/2.0.2/\\n- Documentation: https://github.com/SpinnCompany/Qt-PyQt-PySide-Custom-Widgets\\n- YouTube Tutorials: https://www.youtube.com/@SpinnTV\\n- Website: https://customwidgets.org\\n\\n## Bug Reports & Feedback\\n\\nFound an issue or have suggestions? Please report them on our GitHub Issues page: https://github.com/SpinnCompany/Qt-PyQt-PySide-Custom-Widgets/issues\\n\\n## Special Thanks\\n\\nThank you to all our contributors and the amazing community for your feedback and support! Your input helps make this library better with every release.\\n\\n---\\n\\nHappy coding!\\n\\nFollow us for more updates:\\n- YouTube: https://www.youtube.com/@SpinnTV\\n- Website: https://customwidgets.org\\n- Email: info@customwidgets.org\\n\\n#Python #Qt #PySide #PyQt #GUI #Development #OpenSource #CustomWidgets #Release"},{"id":"custom-variables-in-json-and-qss-style-sheets","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/custom-variables-in-json-and-qss-style-sheets","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-custom-variables-in-json-and-qss-style-sheets.mdx","source":"@site/blog/2025-11-12-custom-variables-in-json-and-qss-style-sheets.mdx","title":"Custom Variables in JSon and QSS Style Sheets","description":"In the Qt Custom Widgets framework, you can define custom variables in your JSON theme configuration and use them throughout your QSS stylesheets. This powerful feature allows you to create consistent, maintainable, and theme-aware styles for your applications.","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":false,"label":"qt custom widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-custom-widgets","description":"Posts about qt custom widgets"},{"inline":false,"label":"qt theming","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-theming","description":"Posts about qt theming"},{"inline":false,"label":"qss styling","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qss-styling","description":"Posts about qss styling"},{"inline":false,"label":"json stylesheet","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/json-stylesheet","description":"Posts about json stylesheet"},{"inline":false,"label":"qt variables","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-variables","description":"Posts about qt variables"},{"inline":false,"label":"pyqt styling","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyqt-styling","description":"Posts about pyqt styling"},{"inline":false,"label":"pyside theming","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside-theming","description":"Posts about pyside theming"},{"inline":false,"label":"qt dark theme","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-dark-theme","description":"Posts about qt dark theme"},{"inline":false,"label":"qt light theme","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-light-theme","description":"Posts about qt light theme"},{"inline":false,"label":"qt design system","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-design-system","description":"Posts about qt design system"},{"inline":false,"label":"qt styling guide","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-styling-guide","description":"Posts about qt styling guide"},{"inline":false,"label":"qt css","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-css","description":"Posts about qt css"},{"inline":false,"label":"qt stylesheets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-stylesheets","description":"Posts about qt stylesheets"},{"inline":false,"label":"qt custom variables","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-custom-variables","description":"Posts about qt custom variables"},{"inline":false,"label":"qt theme engine","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-theme-engine","description":"Posts about qt theme engine"},{"inline":false,"label":"qt application styling","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-application-styling","description":"Posts about qt application styling"},{"inline":false,"label":"python qt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python-qt","description":"Posts about python qt"},{"inline":false,"label":"qt desktop apps","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-desktop-apps","description":"Posts about qt desktop apps"},{"inline":false,"label":"qt ui design","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-ui-design","description":"Posts about qt ui design"},{"inline":false,"label":"qt development","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-development","description":"Posts about qt development"},{"inline":false,"label":"qt best practices","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-best-practices","description":"Posts about qt best practices"},{"inline":false,"label":"qt styling variables","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-styling-variables","description":"Posts about qt styling variables"},{"inline":false,"label":"qt scss","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-scss","description":"Posts about qt scss"},{"inline":false,"label":"qt qss variables","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-qss-variables","description":"Posts about qt qss variables"},{"inline":false,"label":"qt theme switching","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-theme-switching","description":"Posts about qt theme switching"},{"inline":false,"label":"qt color variables","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-color-variables","description":"Posts about qt color variables"},{"inline":false,"label":"qt design tokens","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-design-tokens","description":"Posts about qt design tokens"},{"inline":false,"label":"qt styling system","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-styling-system","description":"Posts about qt styling system"},{"inline":false,"label":"qt json configuration","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-json-configuration","description":"Posts about qt json configuration"},{"inline":false,"label":"qt theme consistency","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt-theme-consistency","description":"Posts about qt theme consistency"}],"readingTime":5.55,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"custom-variables-in-json-and-qss-style-sheets","tags":["qt custom widgets","qt theming","qss styling","json stylesheet","qt variables","pyqt styling","pyside theming","qt dark theme","qt light theme","qt design system","qt styling guide","qt css","qt stylesheets","qt custom variables","qt theme engine","qt application styling","python qt","qt desktop apps","qt ui design","qt development","qt best practices","qt styling variables","qt scss","qt qss variables","qt theme switching","qt color variables","qt design tokens","qt styling system","qt json configuration","qt theme consistency"],"title":"Custom Variables in JSon and QSS Style Sheets"},"unlisted":false,"prevItem":{"title":"V 2.0.2 Released","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/2025-11-12-v-202"},"nextItem":{"title":"Getting Started With Qt Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/getting-started-with-qt-custom-widgets"}},"content":"In the Qt Custom Widgets framework, you can define custom variables in your JSON theme configuration and use them throughout your QSS stylesheets. This powerful feature allows you to create consistent, maintainable, and theme-aware styles for your applications.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n:::warning\\r\\n**Important Note**: Custom variables defined in `\\"Other-variables\\"` must be present in **every** `CustomTheme` object in your JSON file. If a theme is missing a variable that you use in your QSS, it will cause SCSS compilation errors when switching to that theme.\\r\\n:::\\r\\n\\r\\n## Defining Custom Variables in JSON\\r\\n\\r\\nYou can add custom variables to any theme in your `style.json` file using the `\\"Other-variables\\"` section. Make sure to define the same variables in all themes:\\r\\n\\r\\n```json\\r\\n{\\r\\n  \\"Theme-name\\": \\"Qt-Dark-Theme\\",\\r\\n  \\"Background-color\\": \\"#1e1e1e\\",\\r\\n  \\"Text-color\\": \\"#e0e0e0\\",\\r\\n  \\"Accent-color\\": \\"#41cd52\\",\\r\\n  \\"Icons-color\\": \\"#41cd52\\",\\r\\n  \\"Default-Theme\\": true,\\r\\n  \\"Other-variables\\": {\\r\\n    \\"CARD_RADIUS\\": \\"12px\\",\\r\\n    \\"FOOTER_BG\\": \\"#111111\\",\\r\\n    \\"NAV_BG\\": \\"#1e1e1e\\",\\r\\n    \\"CARD_BG\\": \\"#2c2c2c\\",\\r\\n    \\"BORDER_COLOR\\": \\"rgba(65, 205, 82, 0.3)\\",\\r\\n    \\"HOVER_GLOW\\": \\"0 12px 32px rgba(65, 205, 82, 0.45)\\",\\r\\n    \\"GRADIENT\\": \\"linear-gradient(135deg, #41cd52, #2fa440)\\",\\r\\n    \\"SPACING_SM\\": \\"8px\\",\\r\\n    \\"SPACING_MD\\": \\"16px\\",\\r\\n    \\"SPACING_LG\\": \\"24px\\"\\r\\n  }\\r\\n},\\r\\n{\\r\\n  \\"Theme-name\\": \\"Qt-Light-Theme\\",\\r\\n  \\"Background-color\\": \\"#ffffff\\",\\r\\n  \\"Text-color\\": \\"#1e1e1e\\",\\r\\n  \\"Accent-color\\": \\"#41cd52\\",\\r\\n  \\"Icons-color\\": \\"#41cd52\\",\\r\\n  \\"Default-Theme\\": false,\\r\\n  \\"Other-variables\\": {\\r\\n    \\"CARD_RADIUS\\": \\"12px\\",\\r\\n    \\"FOOTER_BG\\": \\"#e5e5e5\\",\\r\\n    \\"NAV_BG\\": \\"#f5f5f5\\",\\r\\n    \\"CARD_BG\\": \\"#f8f8f8\\",\\r\\n    \\"BORDER_COLOR\\": \\"rgba(65, 205, 82, 0.2)\\",\\r\\n    \\"HOVER_GLOW\\": \\"0 12px 32px rgba(65, 205, 82, 0.25)\\",\\r\\n    \\"GRADIENT\\": \\"linear-gradient(135deg, #41cd52, #2fa440)\\",\\r\\n    \\"SPACING_SM\\": \\"8px\\",\\r\\n    \\"SPACING_MD\\": \\"16px\\",\\r\\n    \\"SPACING_LG\\": \\"24px\\"\\r\\n  }\\r\\n}\\r\\n```\\r\\n\\r\\n:::tip\\r\\n**Pro Tip**: Create a template of your custom variables and copy it to every theme in your JSON file to ensure consistency and avoid missing variable errors.\\r\\n:::\\r\\n\\r\\n## Using Custom Variables in QSS\\r\\n\\r\\nOnce defined, these variables become available in your QSS/SCSS files and can be used just like the auto-generated theme variables:\\r\\n\\r\\n### Basic Usage Examples\\r\\n\\r\\n```scss\\r\\n// Card components using custom variables\\r\\nQFrame#card {\\r\\n    background-color: $CARD_BG;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    border: 1px solid $BORDER_COLOR;\\r\\n    margin: $SPACING_MD;\\r\\n    \\r\\n    &:hover {\\r\\n        box-shadow: $HOVER_GLOW;\\r\\n    }\\r\\n}\\r\\n\\r\\n// Navigation using custom background\\r\\nQWidget#navigation {\\r\\n    background-color: $NAV_BG;\\r\\n    border-right: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\n// Footer styling\\r\\nQWidget#footer {\\r\\n    background-color: $FOOTER_BG;\\r\\n    border-top: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n```\\r\\n\\r\\n### Advanced Usage with Gradients\\r\\n\\r\\n```scss\\r\\n// Using custom gradient variables\\r\\nQMainWindow#gradientBackground {\\r\\n    background: $GRADIENT;\\r\\n}\\r\\n\\r\\n// Creating derived gradients\\r\\nQFrame#header {\\r\\n    background: qlineargradient(\\r\\n        x1:0, y1:0, x2:1, y2:0,\\r\\n        stop:0 $CARD_BG,\\r\\n        stop:1 $NAV_BG\\r\\n    );\\r\\n    border-radius: $CARD_RADIUS;\\r\\n}\\r\\n```\\r\\n\\r\\n### Consistent Spacing System\\r\\n\\r\\n```scss\\r\\n// Using spacing variables for consistency\\r\\nQWidget#container {\\r\\n    padding: $SPACING_LG;\\r\\n}\\r\\n\\r\\nQPushButton {\\r\\n    padding: $SPACING_SM $SPACING_MD;\\r\\n    margin: $SPACING_SM;\\r\\n}\\r\\n\\r\\nQLabel {\\r\\n    margin: $SPACING_SM;\\r\\n}\\r\\n\\r\\nQVBoxLayout, QHBoxLayout {\\r\\n    spacing: $SPACING_MD;\\r\\n    margin: $SPACING_SM;\\r\\n}\\r\\n```\\r\\n\\r\\n## Complete Theme-Aware QSS Example\\r\\n\\r\\nHere\'s a complete QSS stylesheet that leverages both auto-generated and custom variables:\\r\\n\\r\\n```scss\\r\\n// ===================================================\\r\\n// APPLICATION LAYOUT STYLES\\r\\n// ===================================================\\r\\n\\r\\nQMainWindow, #centralwidget {\\r\\n    background-color: $COLOR_BACKGROUND_1;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// CARD SYSTEM\\r\\n// ===================================================\\r\\n\\r\\nQFrame#card {\\r\\n    background-color: $CARD_BG;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    border: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n    \\r\\n    &:hover {\\r\\n        box-shadow: $HOVER_GLOW;\\r\\n    }\\r\\n}\\r\\n\\r\\nQFrame#card QLabel#title {\\r\\n    color: $COLOR_TEXT_1;\\r\\n    font-size: 16px;\\r\\n    font-weight: bold;\\r\\n    margin-bottom: $SPACING_SM;\\r\\n}\\r\\n\\r\\nQFrame#card QLabel#content {\\r\\n    color: $COLOR_TEXT_2;\\r\\n    font-size: 14px;\\r\\n    margin-bottom: $SPACING_SM;\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// NAVIGATION SYSTEM\\r\\n// ===================================================\\r\\n\\r\\nQWidget#navigation {\\r\\n    background-color: $NAV_BG;\\r\\n    border-right: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\nQPushButton#navButton {\\r\\n    background-color: transparent;\\r\\n    color: $COLOR_TEXT_2;\\r\\n    text-align: left;\\r\\n    padding: $SPACING_MD;\\r\\n    border-radius: calc($CARD_RADIUS / 2);\\r\\n    margin: 2px $SPACING_SM;\\r\\n    \\r\\n    &:hover {\\r\\n        background-color: $COLOR_BACKGROUND_2;\\r\\n        color: $COLOR_TEXT_1;\\r\\n    }\\r\\n    \\r\\n    &:checked {\\r\\n        background-color: $COLOR_ACCENT_1;\\r\\n        color: $COLOR_BACKGROUND_1;\\r\\n    }\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// FORM SYSTEM\\r\\n// ===================================================\\r\\n\\r\\nQLineEdit, QComboBox, QTextEdit {\\r\\n    background-color: $COLOR_BACKGROUND_2;\\r\\n    color: $COLOR_TEXT_1;\\r\\n    border: 1px solid $BORDER_COLOR;\\r\\n    border-radius: calc($CARD_RADIUS / 3);\\r\\n    padding: $SPACING_SM $SPACING_MD;\\r\\n    font-size: 14px;\\r\\n    margin-bottom: $SPACING_SM;\\r\\n    \\r\\n    &:focus {\\r\\n        border-color: $COLOR_ACCENT_1;\\r\\n        background-color: $COLOR_BACKGROUND_3;\\r\\n    }\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// BUTTON VARIANTS\\r\\n// ===================================================\\r\\n\\r\\nQPushButton {\\r\\n    background-color: $COLOR_BACKGROUND_2;\\r\\n    color: $COLOR_TEXT_1;\\r\\n    border: 1px solid $BORDER_COLOR;\\r\\n    border-radius: calc($CARD_RADIUS / 2);\\r\\n    padding: $SPACING_SM $SPACING_MD;\\r\\n    font-weight: 500;\\r\\n    margin: $SPACING_SM;\\r\\n    \\r\\n    &:hover {\\r\\n        background-color: $COLOR_ACCENT_1;\\r\\n        color: $COLOR_BACKGROUND_1;\\r\\n    }\\r\\n}\\r\\n\\r\\nQPushButton#primaryButton {\\r\\n    background-color: $COLOR_ACCENT_1;\\r\\n    color: $COLOR_BACKGROUND_1;\\r\\n    font-weight: bold;\\r\\n}\\r\\n\\r\\nQPushButton#secondaryButton {\\r\\n    background-color: $CARD_BG;\\r\\n    color: $COLOR_TEXT_1;\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// LAYOUT COMPONENTS\\r\\n// ===================================================\\r\\n\\r\\nQWidget#header {\\r\\n    background-color: $NAV_BG;\\r\\n    border-bottom: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\nQWidget#footer {\\r\\n    background-color: $FOOTER_BG;\\r\\n    border-top: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\nQWidget#sidebar {\\r\\n    background-color: $CARD_BG;\\r\\n    border-right: 1px solid $BORDER_COLOR;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\n// ===================================================\\r\\n// UTILITY STYLES USING OBJECT NAMES\\r\\n// ===================================================\\r\\n\\r\\n// Text utilities\\r\\nQLabel#textTitle {\\r\\n    color: $COLOR_TEXT_1;\\r\\n    font-size: 18px;\\r\\n    font-weight: bold;\\r\\n    margin-bottom: $SPACING_MD;\\r\\n}\\r\\n\\r\\nQLabel#textSubtitle {\\r\\n    color: $COLOR_TEXT_2;\\r\\n    font-size: 14px;\\r\\n    margin-bottom: $SPACING_SM;\\r\\n}\\r\\n\\r\\nQLabel#textMuted {\\r\\n    color: $COLOR_TEXT_3;\\r\\n    font-size: 12px;\\r\\n}\\r\\n\\r\\n// Background utilities\\r\\nQWidget#bgCard {\\r\\n    background-color: $CARD_BG;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    padding: $SPACING_MD;\\r\\n}\\r\\n\\r\\nQWidget#bgNav {\\r\\n    background-color: $NAV_BG;\\r\\n}\\r\\n\\r\\nQWidget#bgFooter {\\r\\n    background-color: $FOOTER_BG;\\r\\n}\\r\\n\\r\\n// Border utilities\\r\\nQWidget#borderAll {\\r\\n    border: 1px solid $BORDER_COLOR;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n}\\r\\n\\r\\nQWidget#borderBottom {\\r\\n    border-bottom: 1px solid $BORDER_COLOR;\\r\\n}\\r\\n\\r\\nQWidget#borderTop {\\r\\n    border-top: 1px solid $BORDER_COLOR;\\r\\n}\\r\\n```\\r\\n\\r\\n:::warning\\r\\n**Troubleshooting Tip**: If you encounter SCSS compilation errors when switching themes, check that all custom variables used in your QSS are defined in the currently active theme\'s `\\"Other-variables\\"` section.\\r\\n:::\\r\\n\\r\\n## Best Practices for Custom Variables\\r\\n\\r\\n### 1. Semantic Variable Names\\r\\nUse names that describe the purpose, not the value:\\r\\n```json\\r\\n\\"Other-variables\\": {\\r\\n    \\"CARD_RADIUS\\": \\"12px\\",           // Good\\r\\n    \\"HEADER_HEIGHT\\": \\"60px\\",         // Good\\r\\n    \\"PRIMARY_SPACING\\": \\"16px\\",       // Good\\r\\n    \\"blue_color\\": \\"#41cd52\\"          // Avoid - too specific\\r\\n}\\r\\n```\\r\\n\\r\\n### 2. Create a Design System\\r\\nDefine a consistent set of variables and ensure they exist in all themes:\\r\\n```json\\r\\n\\"Other-variables\\": {\\r\\n    // Spacing scale\\r\\n    \\"SPACING_XS\\": \\"4px\\",\\r\\n    \\"SPACING_SM\\": \\"8px\\", \\r\\n    \\"SPACING_MD\\": \\"16px\\",\\r\\n    \\"SPACING_LG\\": \\"24px\\",\\r\\n    \\"SPACING_XL\\": \\"32px\\",\\r\\n    \\r\\n    // Border radius scale\\r\\n    \\"RADIUS_SM\\": \\"4px\\",\\r\\n    \\"RADIUS_MD\\": \\"8px\\",\\r\\n    \\"RADIUS_LG\\": \\"12px\\",\\r\\n    \\"RADIUS_XL\\": \\"16px\\",\\r\\n    \\r\\n    // Component-specific\\r\\n    \\"CARD_BG\\": \\"#2c2c2c\\",\\r\\n    \\"NAV_BG\\": \\"#1e1e1e\\",\\r\\n    \\"HEADER_HEIGHT\\": \\"60px\\"\\r\\n}\\r\\n```\\r\\n\\r\\n:::tip\\r\\n**Consistency Tip**: Create a master list of your custom variables and use it as a checklist when adding new themes to ensure you don\'t miss any variables.\\r\\n:::\\r\\n\\r\\n### 3. Theme-Specific Adjustments\\r\\nYou can override variables for specific themes while keeping the same variable names:\\r\\n```json\\r\\n{\\r\\n  \\"Theme-name\\": \\"Qt-Light-Theme\\",\\r\\n  \\"Background-color\\": \\"#ffffff\\",\\r\\n  \\"Text-color\\": \\"#1e1e1e\\",\\r\\n  \\"Other-variables\\": {\\r\\n    \\"CARD_BG\\": \\"#f8f8f8\\",\\r\\n    \\"NAV_BG\\": \\"#f5f5f5\\",\\r\\n    \\"FOOTER_BG\\": \\"#e5e5e5\\",\\r\\n    \\"BORDER_COLOR\\": \\"rgba(65, 205, 82, 0.2)\\",\\r\\n    \\"HOVER_GLOW\\": \\"0 12px 32px rgba(65, 205, 82, 0.25)\\",\\r\\n    // Keep all other variables the same as other themes\\r\\n    \\"SPACING_SM\\": \\"8px\\",\\r\\n    \\"SPACING_MD\\": \\"16px\\",\\r\\n    \\"CARD_RADIUS\\": \\"12px\\"\\r\\n  }\\r\\n}\\r\\n```\\r\\n\\r\\n### 4. Using Variables in Python Code\\r\\nYou can also access these variables in your Python code:\\r\\n```python\\r\\nfrom Custom_Widgets.QAppSettings import QAppSettings\\r\\n\\r\\nclass MainWindow(QMainWindow):\\r\\n    def __init__(self):\\r\\n        super().__init__()\\r\\n        # Access theme variables\\r\\n        card_radius = self.theme.CARD_RADIUS\\r\\n        spacing_md = self.theme.SPACING_MD\\r\\n        \\r\\n        # Use in dynamic styling\\r\\n        self.ui.some_widget.setStyleSheet(f\\"\\"\\"\\r\\n            border-radius: {card_radius};\\r\\n            padding: {spacing_md};\\r\\n        \\"\\"\\")\\r\\n```\\r\\n\\r\\n:::warning\\r\\n**Development Note**: When adding new custom variables to your QSS, remember to update all themes in your JSON file with the new variables to prevent theme switching errors.\\r\\n:::\\r\\n\\r\\n## Benefits of Using Custom Variables\\r\\n\\r\\n1. **Consistency**: Ensure visual consistency across your application\\r\\n2. **Maintainability**: Change values in one place to update everywhere\\r\\n3. **Theme Cohesion**: Custom variables work seamlessly with theme switching\\r\\n4. **Developer Experience**: Clear, semantic variable names improve code readability\\r\\n5. **Scalability**: Easy to add new components that follow the same design system\\r\\n\\r\\nBy leveraging custom variables in your JSON themes, you create a robust, maintainable styling system that scales with your application and provides a consistent user experience across different themes."},{"id":"getting-started-with-qt-custom-widgets","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/getting-started-with-qt-custom-widgets","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-getting-started-with-qt-custom-widgets.md","source":"@site/blog/2025-11-12-getting-started-with-qt-custom-widgets.md","title":"Getting Started With Qt Custom Widgets","description":"Step 1: Install Python and Create Virtual Environment","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":false,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside6","description":"Posts about PySide6"},{"inline":false,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python","description":"Posts about Python"},{"inline":false,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui","description":"Posts about GUI"},{"inline":false,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets","description":"Posts about Custom Widgets"},{"inline":false,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial","description":"Posts about Tutorial"},{"inline":false,"label":"Qt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt","description":"Posts about Qt"},{"inline":false,"label":"PyQt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyqt","description":"Posts about PyQt"},{"inline":false,"label":"Gui. Interface","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui-interface","description":"Posts about Gui. Interface"},{"inline":false,"label":"Desktop","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/desktop","description":"Posts about Desktop"}],"readingTime":7.55,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"getting-started-with-qt-custom-widgets","tags":["PySide6","Python","GUI","Custom Widgets","Tutorial","Qt","PyQt","Gui. Interface","Desktop"],"title":"Getting Started With Qt Custom Widgets"},"unlisted":false,"prevItem":{"title":"Custom Variables in JSon and QSS Style Sheets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/custom-variables-in-json-and-qss-style-sheets"},"nextItem":{"title":"Qt Theme Styling Guide: Json Stylesheet","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-json-stylesheet"}},"content":"## Step 1: Install Python and Create Virtual Environment\\n\\n### Install Python\\nFirst, ensure you have Python 3.7 or higher installed:\\n\\n\x3c!-- truncate --\x3e\\n\\n**Windows:**\\n```bash\\n# Download from python.org or use winget\\nwinget install Python.Python.3.11\\n```\\n\\n**macOS:**\\n```bash\\n# Using Homebrew\\nbrew install python\\n```\\n\\n**Linux (Ubuntu/Debian):**\\n```bash\\nsudo apt update\\nsudo apt install python3 python3-pip python3-venv\\n```\\n\\n### Create Virtual Environment\\nAlways use a virtual environment to manage dependencies:\\n\\n```bash\\n# Create project directory\\nmkdir my_qt_project\\ncd my_qt_project\\n\\n# Create virtual environment\\npython -m venv venv\\n\\n# Activate virtual environment\\n# Windows:\\nvenv\\\\Scripts\\\\activate\\n# macOS/Linux:\\nsource venv/bin/activate\\n```\\n\\nYour terminal should now show `(venv)` indicating the virtual environment is active.\\n\\n---\\n\\n## Step 2: Install Qt Binding\\n\\n**Important:** Make sure your virtual environment is activated (you see `(venv)` in your terminal).\\n\\nChoose and install one of these Qt bindings:\\n\\n### Option 1: PySide6 (Recommended)\\n```bash\\npip install PySide6\\n```\\n\\n### Option 2: PyQt6\\n```bash\\npip install PyQt6\\n```\\n\\n### Option 3: PySide2\\n```bash\\npip install PySide2\\n```\\n\\n### Option 4: PyQt5\\n```bash\\npip install PyQt5\\n```\\n\\n**Note:** For this tutorial, we\'ll use PySide6 as it\'s the most modern and freely available.\\n\\n---\\n\\n## Step 3: Install Custom Widgets\\n\\nInstall the custom widgets package (make sure venv is active):\\n\\n```bash\\npip install QT-PyQt-PySide-Custom-Widgets\\n```\\n\\nVerify installation:\\n```bash\\npython -c \\"import Custom_Widgets; print(\'Custom Widgets installed successfully!\')\\"\\n```\\n\\n---\\n\\n## Step 4: Create Your First Project\\n\\n### Method A: Using the Project Creator (Recommended for Beginners)\\n\\n**Important:** Run this command from INSIDE your activated virtual environment folder:\\n\\n```bash\\n# You should be in your project directory with venv activated\\n# Your terminal should show: (venv) path/to/your/project$\\n\\n# Run project creator FROM INSIDE THE VENV FOLDER\\nCustom_Widgets --create-project\\n```\\n\\n**What happens when you run the project creator:**\\n1. It detects your current directory as the project location\\n2. It checks if the folder is empty (or only contains logs)\\n3. It guides you through the setup process interactively\\n\\nThe project creator will guide you through:\\n1. **Qt Binding Selection**: Choose your Qt library\\n2. **Color Scheme**: Select icons and theme colors\\n3. **App Information**: Enter app name and organization details\\n4. **Automatic Setup**: Creates all necessary files and folders\\n\\n### Correct Folder Structure Example:\\n```\\nmy_qt_project/          # Your project folder\\n\u251c\u2500\u2500 venv/               # Virtual environment (already created)\\n\u2502   \u251c\u2500\u2500 bin/            # or Scripts/ on Windows\\n\u2502   \u251c\u2500\u2500 lib/\\n\u2502   \u2514\u2500\u2500 pyvenv.cfg\\n\u2514\u2500\u2500 (project files will be created here by the creator)\\n```\\n\\n**Common Mistake to Avoid:**\\n- Don\'t run the command from inside the `venv` folder\\n- Run it from your project root folder where `venv` is located\\n\\n### Method B: Manual Setup (For Advanced Users)\\nIf you prefer manual setup, create this structure in your project root:\\n```\\nmy_qt_project/\\n\u251c\u2500\u2500 venv/               # Virtual environment\\n\u251c\u2500\u2500 main.py             # Main application file\\n\u251c\u2500\u2500 ui/                 # UI files directory\\n\u2502   \u2514\u2500\u2500 main_window.ui\\n\u251c\u2500\u2500 json-styles/        # Theme configuration\\n\u2502   \u2514\u2500\u2500 style.json\\n\u251c\u2500\u2500 requirements.txt    # Dependencies\\n\u2514\u2500\u2500 README.md          # Documentation\\n```\\n\\n---\\n\\n## Step 5: Understanding the Project Structure\\n\\nAfter running the project creator from inside your venv folder, you\'ll have:\\n\\n```\\nmy_qt_project/\\n\u251c\u2500\u2500 venv/               # Virtual environment\\n\u251c\u2500\u2500 main.py              # Main application file\\n\u251c\u2500\u2500 ui/                  # UI files directory\\n\u2502   \u2514\u2500\u2500 QCustomQMainWindow.ui\\n\u251c\u2500\u2500 json-styles/         # Theme configuration\\n\u2502   \u2514\u2500\u2500 style.json\\n\u251c\u2500\u2500 requirements.txt     # Dependencies\\n\u2514\u2500\u2500 README.md           # Documentation\\n```\\n\\n---\\n\\n## Step 6: Register Custom Widgets with Qt Designer\\n\\nBefore designing your interface, register the custom widgets (from your activated venv):\\n\\n```bash\\n# Register widgets with Qt Designer\\nCustom_Widgets --register-widgets\\n```\\n\\n**Expected Output:**\\n```\\nRegistering QCustomQMainWindow...\\nRegistering QCustomSidebar...\\nRegistering QCustomProgressBar...\\n... (all widgets registered successfully)\\n```\\n\\n---\\n\\n## Step 7: Launch Qt Designer with Custom Widgets\\n\\nStart Qt Designer with the custom widgets loaded (from activated venv):\\n\\n```bash\\n# Launch Qt Designer with custom widgets\\nCustom_Widgets --start-designer --plugins\\n```\\n\\n**Alternative methods:**\\n```bash\\n# If the above doesn\'t work, try:\\ndesigner\\n# or\\npyside6-designer\\n# or\\nqt5-designer\\n```\\n\\n---\\n\\n## Step 8: Designing Your Interface in Qt Designer\\n\\n### Finding Custom Widgets\\nWhen Qt Designer opens, look for these widget groups in the widget box:\\n\\n1. **MainWindow Section**:\\n   - `QCustomQMainWindow` - Enhanced main window with theme support\\n\\n2. **Sidebar Section**:\\n   - `QCustomSidebar` - Customizable sidebar navigation\\n   - `QCustomSidebarButton` - Buttons for sidebar\\n   - `QCustomSidebarLabel` - Labels for sidebar\\n\\n3. **Progressbars Section**:\\n   - `QCustomRoundProgressBar` - Circular progress indicator\\n   - `AnalogGaugeWidget` - Analog gauge display\\n\\n4. **Component Container Section**:\\n   - `QCustomComponent` - Container for organizing widgets\\n   - `QCustomComponentContainer` - Main container component\\n\\n### Step-by-Step Design Process\\n\\n1. **Start with QCustomQMainWindow**:\\n   - Drag `QCustomQMainWindow` from the widget box to the form\\n   - This becomes your main application window\\n\\n2. **Add a Sidebar**:\\n   - Drag `QCustomSidebar` to the left side of your main window\\n   - Add `QCustomSidebarButton` widgets inside the sidebar\\n   - Set button text and icons in the property editor\\n\\n3. **Add Content Area**:\\n   - Use `QCustomComponent` as content containers\\n   - Add standard Qt widgets (buttons, labels, etc.) inside components\\n   - Use `QCustomQStackedWidget` to manage multiple pages\\n\\n4. **Style Your Interface**:\\n   - Use the property editor to set object names\\n   - Apply custom styles through the JSON configuration later\\n\\n5. **Save Your Design**:\\n   - Save the file as `main_window.ui` in the `ui/` folder\\n   - Qt Designer files use `.ui` extension\\n\\n---\\n\\n## Step 9: Automatic UI File Conversion\\n\\n### Start File Monitoring (Recommended)\\nKeep this running while you design (from activated venv):\\n\\n```bash\\n# Monitor UI folder for changes\\nCustom_Widgets --monitor-ui ui --qt-library PySide6\\n```\\n\\n**What this does:**\\n- Watches the `ui/` folder for any changes\\n- Automatically converts `.ui` files to Python when you save\\n- Updates your application in real-time\\n\\n### Manual Conversion\\nIf you prefer manual conversion:\\n\\n```bash\\n# Convert specific file\\nCustom_Widgets --convert-ui ui/main_window.ui --qt-library PySide6\\n\\n# Convert all files in folder\\nCustom_Widgets --convert-ui ui --qt-library PySide6\\n```\\n\\n---\\n\\n## Step 10: Customize Your App Theme\\n\\nEdit the `json-styles/style.json` file to customize your app\'s appearance:\\n\\n```json\\n{\\n    \\"QtBinding\\": \\"PySide6\\",\\n    \\"QMainWindow\\": {\\n        \\"title\\": \\"My Awesome App\\"\\n    },\\n    \\"QSettings\\": {\\n        \\"AppSettings\\": {\\n            \\"OrginizationName\\": \\"My Company\\",\\n            \\"ApplicationName\\": \\"My App\\",\\n            \\"OrginizationDormain\\": \\"myapp.org\\"\\n        },\\n        \\"ThemeSettings\\": {\\n            \\"QtDesignerIconsColor\\": \\"#ffffff\\",\\n            \\"CustomThemes\\": [\\n                {\\n                    \\"Background-color\\": \\"#2b2b2b\\",\\n                    \\"Text-color\\": \\"#ffffff\\",\\n                    \\"Accent-color\\": \\"#0078d4\\",\\n                    \\"Icons-color\\": \\"#ffffff\\",\\n                    \\"Theme-name\\": \\"Default Dark\\",\\n                    \\"Default-Theme\\": true\\n                }\\n            ]\\n        }\\n    }\\n}\\n```\\n\\n**Key Configuration Options:**\\n- `Background-color`: Main app background\\n- `Text-color`: Default text color\\n- `Accent-color`: Primary accent color for buttons, highlights\\n- `Icons-color`: Color of all icons in the app\\n\\n---\\n\\n## Step 11: Run Your Application\\n\\nExecute your application (from activated venv):\\n\\n```bash\\npython main.py\\n```\\n\\nYour custom-styled application should launch with:\\n- The theme colors you configured\\n- All custom widgets functioning\\n- Your designed interface layout\\n\\n---\\n\\n## Step 12: Development Workflow Tips\\n\\n### Efficient Development Cycle\\n1. **Activate Venv**: Always start with `source venv/bin/activate` (or `venv\\\\Scripts\\\\activate` on Windows)\\n2. **Design**: Work in Qt Designer with custom widgets\\n3. **Save**: Save your `.ui` file (auto-conversion happens if monitoring)\\n4. **Test**: Run your app to see changes\\n5. **Repeat**: Go back to design and continue iterating\\n\\n### Useful Commands for Daily Use (Run from activated venv)\\n```bash\\n# Start monitoring when beginning work\\nCustom_Widgets --monitor-ui ui --qt-library PySide6\\n\\n# Launch designer when needed\\nCustom_Widgets --start-designer --plugins\\n\\n# Run your app\\npython main.py\\n```\\n\\n### Complete Workflow Example\\n```bash\\n# 1. Start fresh each day\\ncd my_qt_project\\nsource venv/bin/activate  # or venv\\\\Scripts\\\\activate on Windows\\n\\n# 2. Start file monitoring (keep this terminal open)\\nCustom_Widgets --monitor-ui ui --qt-library PySide6\\n\\n# 3. In another terminal, launch designer\\ncd my_qt_project\\nsource venv/bin/activate\\nCustom_Widgets --start-designer --plugins\\n\\n# 4. When ready to test\\npython main.py\\n```\\n\\n---\\n\\n## Step 13: Advanced Customization\\n\\n### Creating Multiple Themes\\nAdd additional themes to your `style.json`:\\n\\n```json\\n\\"CustomThemes\\": [\\n    {\\n        \\"Background-color\\": \\"#2b2b2b\\",\\n        \\"Text-color\\": \\"#ffffff\\",\\n        \\"Accent-color\\": \\"#0078d4\\",\\n        \\"Icons-color\\": \\"#ffffff\\",\\n        \\"Theme-name\\": \\"Dark Blue\\",\\n        \\"Default-Theme\\": true\\n    },\\n    {\\n        \\"Background-color\\": \\"#f0f0f0\\",\\n        \\"Text-color\\": \\"#000000\\",\\n        \\"Accent-color\\": \\"#e74c3c\\",\\n        \\"Icons-color\\": \\"#000000\\",\\n        \\"Theme-name\\": \\"Light Red\\",\\n        \\"Default-Theme\\": false\\n    }\\n]\\n```\\n\\n### Custom Widget Properties\\nEach custom widget has specific properties you can set in Qt Designer:\\n\\n- **QCustomSidebar**: `backgroundColor`, `activeColor`, `iconSize`\\n- **QCustomProgressBar**: `progressColor`, `background_color`, `text_color`\\n- **QCustomQMainWindow**: `enableCustomTitleBar`, `enableGradient`\\n\\n---\\n\\n## Troubleshooting Common Issues\\n\\n### Virtual Environment Issues\\n```bash\\n# Check if venv is activated\\nwhich python  # Should point to venv directory\\n\\n# If not activated:\\nsource venv/bin/activate  # macOS/Linux\\nvenv\\\\Scripts\\\\activate     # Windows\\n```\\n\\n### Widgets Not Showing in Qt Designer\\n```bash\\n# Re-register widgets (from activated venv)\\nCustom_Widgets --register-widgets\\n\\n# Restart Qt Designer\\nCustom_Widgets --start-designer --plugins\\n```\\n\\n### UI Files Not Converting\\n```bash\\n# Check if monitoring is running (from activated venv)\\nCustom_Widgets --monitor-ui ui --qt-library PySide6\\n\\n# Manual conversion (from activated venv)\\nCustom_Widgets --convert-ui ui/main_window.ui --qt-library PySide6\\n```\\n\\n### Import Errors\\n```bash\\n# Ensure package is installed in venv\\npip install QT-PyQt-PySide-Custom-Widgets\\n\\n# Check virtual environment is activated\\nwhich python  # Should point to venv directory\\n```\\n\\n### Project Creator Not Working\\n```bash\\n# Make sure you\'re in the correct directory\\npwd  # Should show your project folder, not inside venv\\n\\n# Check folder contents\\nls -la  # Should show venv folder and your project files\\n\\n# If you accidentally ran creator in wrong location:\\n# Delete the generated files and run again from correct location\\n```\\n\\n---\\n\\n## Next Steps\\n\\nNow that you have a basic application running:\\n\\n1. **Explore More Widgets**: Try different custom widgets in your designs\\n2. **Custom Styles**: Experiment with different color schemes in the JSON file\\n3. **Advanced Layouts**: Combine custom widgets with standard Qt widgets\\n4. **Animation**: Add transitions and animations to your interface\\n5. **Database Integration**: Connect your GUI to databases or APIs\\n\\n## Resources\\n\\n- **Documentation**: [GitHub Repository](https://github.com/SpinnCompany/Qt-PyQt-PySide-Custom-Widgets)\\n- **Video Tutorials**: [SPINN TV YouTube Channel](https://www.youtube.com/@SpinnTV)\\n- **Community Support**: GitHub Issues and Discussions\\n\\n---\\n\\n**Congratulations!** You\'ve successfully set up a Qt application with custom widgets using proper virtual environment practices. The automated workflow will make your development process much smoother as you continue building your application.\\n\\n**Key Takeaway:** Always remember to activate your virtual environment before running any Custom_Widgets commands or your Python application!"},{"id":"qt-theme-styling-guide-json-stylesheet","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-json-stylesheet","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-qt-theme-styling-guide-json-stylesheet.md","source":"@site/blog/2025-11-12-qt-theme-styling-guide-json-stylesheet.md","title":"Qt Theme Styling Guide: Json Stylesheet","description":"In this guide, we\'ll walk through creating professional Qt Dark and Light themes for your custom widgets applications. These themes follow Qt\'s design language while providing modern, visually appealing interfaces.","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":false,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside6","description":"Posts about PySide6"},{"inline":false,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python","description":"Posts about Python"},{"inline":false,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui","description":"Posts about GUI"},{"inline":false,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets","description":"Posts about Custom Widgets"},{"inline":false,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial","description":"Posts about Tutorial"},{"inline":false,"label":"version","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/version","description":"Posts about version"},{"inline":false,"label":"news","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/news","description":"Posts about news"}],"readingTime":3.97,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"qt-theme-styling-guide-json-stylesheet","tags":["PySide6","Python","GUI","Custom Widgets","Tutorial","version","news"],"title":"Qt Theme Styling Guide: Json Stylesheet"},"unlisted":false,"prevItem":{"title":"Getting Started With Qt Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/getting-started-with-qt-custom-widgets"},"nextItem":{"title":"Qt Theme Styling Guide: Qss/Css Stylesheet","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-qsscss-stylesheet"}},"content":"In this guide, we\'ll walk through creating professional Qt Dark and Light themes for your custom widgets applications. These themes follow Qt\'s design language while providing modern, visually appealing interfaces.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## Theme Color Palettes\\r\\n\\r\\n### Qt Dark Theme Colors\\r\\n- **Background**: `#1e1e1e` (Dark gray)\\r\\n- **Text**: `#e0e0e0` (Light gray)\\r\\n- **Accent**: `#41cd52` (Qt green)\\r\\n- **Icons**: `#41cd52` (Qt green)\\r\\n- **Cards**: `#2c2c2c` (Slightly lighter dark gray)\\r\\n- **Footer**: `#111111` (Near black)\\r\\n\\r\\n### Qt Light Theme Colors  \\r\\n- **Background**: `#ffffff` (Pure white)\\r\\n- **Text**: `#1e1e1e` (Dark gray)\\r\\n- **Accent**: `#41cd52` (Qt green)\\r\\n- **Icons**: `#41cd52` (Qt green)\\r\\n- **Cards**: `#f8f8f8` (Off-white)\\r\\n- **Footer**: `#e5e5e5` (Light gray)\\r\\n\\r\\n## Complete Theme Configuration\\r\\n\\r\\nHere\'s how to implement both themes in your `style.json`:\\r\\n\\r\\n```json\\r\\n{\\r\\n  \\"QSettings\\": [\\r\\n    {\\r\\n      \\"ThemeSettings\\": {\\r\\n        \\"QtDesignerIconsColor\\": \\"#41CD52\\",\\r\\n        \\"CustomThemes\\": [\\r\\n          {\\r\\n            \\"Theme-name\\": \\"Qt-Dark-Theme\\",\\r\\n            \\"Background-color\\": \\"#1e1e1e\\",\\r\\n            \\"Text-color\\": \\"#e0e0e0\\",\\r\\n            \\"Accent-color\\": \\"#41cd52\\",\\r\\n            \\"Icons-color\\": \\"#41cd52\\",\\r\\n            \\"Default-Theme\\": true,\\r\\n            \\"Create-icons\\": true,\\r\\n            \\"Other-variables\\": {\\r\\n              \\"CARD_RADIUS\\": \\"12px\\",\\r\\n              \\"FOOTER_BG\\": \\"#111111\\",\\r\\n              \\"NAV_BG\\": \\"#1e1e1e\\",\\r\\n              \\"CARD_BG\\": \\"#2c2c2c\\",\\r\\n              \\"BORDER_COLOR\\": \\"rgba(65, 205, 82, 0.3)\\",\\r\\n              \\"HOVER_GLOW\\": \\"0 12px 32px rgba(65, 205, 82, 0.45)\\",\\r\\n              \\"GRADIENT\\": \\"linear-gradient(135deg, #41cd52, #2fa440)\\"\\r\\n            }\\r\\n          },\\r\\n          {\\r\\n            \\"Theme-name\\": \\"Qt-Light-Theme\\",\\r\\n            \\"Background-color\\": \\"#ffffff\\",\\r\\n            \\"Text-color\\": \\"#1e1e1e\\",\\r\\n            \\"Accent-color\\": \\"#41cd52\\",\\r\\n            \\"Icons-color\\": \\"#41cd52\\",\\r\\n            \\"Default-Theme\\": false,\\r\\n            \\"Create-icons\\": true,\\r\\n            \\"Other-variables\\": {\\r\\n              \\"CARD_RADIUS\\": \\"12px\\",\\r\\n              \\"FOOTER_BG\\": \\"#e5e5e5\\",\\r\\n              \\"NAV_BG\\": \\"#f5f5f5\\",\\r\\n              \\"CARD_BG\\": \\"#f8f8f8\\",\\r\\n              \\"BORDER_COLOR\\": \\"rgba(65, 205, 82, 0.2)\\",\\r\\n              \\"HOVER_GLOW\\": \\"0 12px 32px rgba(65, 205, 82, 0.25)\\",\\r\\n              \\"GRADIENT\\": \\"linear-gradient(135deg, #41cd52, #2fa440)\\"\\r\\n            }\\r\\n          }\\r\\n        ]\\r\\n      }\\r\\n    }\\r\\n  ]\\r\\n}\\r\\n```\\r\\n\\r\\n## Key Design Principles\\r\\n\\r\\n### 1. Color Contrast\\r\\n- **Dark Theme**: High contrast between background (`#1e1e1e`) and text (`#e0e0e0`)\\r\\n- **Light Theme**: Strong contrast between background (`#ffffff`) and text (`#1e1e1e`)\\r\\n- **Accessibility**: Both themes maintain WCAG AA compliance for text readability\\r\\n\\r\\n### 2. Consistent Accent Color\\r\\n- Uses Qt\'s signature green (`#41cd52`) across both themes\\r\\n- Provides visual consistency when switching between themes\\r\\n- Green color represents Qt\'s brand identity\\r\\n\\r\\n### 3. Layered Backgrounds\\r\\n- **Dark Theme**: Three levels of darkness for depth\\r\\n- **Light Theme**: Three levels of lightness for hierarchy\\r\\n- Each layer serves a specific purpose in the UI\\r\\n\\r\\n### 4. Modern Effects\\r\\n- **Border Radius**: Consistent 12px rounded corners\\r\\n- **Shadows**: Theme-appropriate glow effects\\r\\n- **Gradients**: Subtle green gradients for visual interest\\r\\n\\r\\n## Theme Variables Explained\\r\\n\\r\\n### Core Colors\\r\\n- `Background-color`: Main application background\\r\\n- `Text-color`: Primary text color for readability  \\r\\n- `Accent-color`: Primary brand color for interactive elements\\r\\n- `Icons-color`: Color for all icon assets\\r\\n\\r\\n### Additional Variables\\r\\n- `CARD_RADIUS`: Border radius for cards and containers\\r\\n- `FOOTER_BG`: Background color for footer areas\\r\\n- `NAV_BG`: Background for navigation elements\\r\\n- `CARD_BG`: Background for card components\\r\\n- `BORDER_COLOR`: Border colors with theme-appropriate opacity\\r\\n- `HOVER_GLOW`: Shadow effects for interactive states\\r\\n- `GRADIENT`: CSS gradients for visual enhancements\\r\\n\\r\\n## Implementation Tips\\r\\n\\r\\n### 1. Setting Default Theme\\r\\n```json\\r\\n\\"Default-Theme\\": true\\r\\n```\\r\\nSet this to `true` for your preferred default theme. The other theme should have `false`.\\r\\n\\r\\n### 2. Icon Generation\\r\\n```json\\r\\n\\"Create-icons\\": true\\r\\n```\\r\\nThis ensures icons are automatically generated in your theme colors.\\r\\n\\r\\n### 3. Opacity Adjustments\\r\\nNotice how border colors use rgba with different opacity:\\r\\n- Dark theme: `rgba(65, 205, 82, 0.3)` (more visible)\\r\\n- Light theme: `rgba(65, 205, 82, 0.2)` (more subtle)\\r\\n\\r\\n### 4. Shadow Intensity\\r\\n- Dark theme shadows are more pronounced (`0.45` opacity)\\r\\n- Light theme shadows are more subtle (`0.25` opacity)\\r\\n\\r\\n## Theme Switching\\r\\n\\r\\nTo implement theme switching in your application:\\r\\n\\r\\n1. Set one theme as default with `\\"Default-Theme\\": true`\\r\\n2. Use the other theme for the alternative mode\\r\\n3. Implement a toggle mechanism in your UI\\r\\n4. Reload the theme configuration when switching\\r\\n\\r\\n## Benefits of This Approach\\r\\n\\r\\n### 1. Brand Consistency\\r\\n- Maintains Qt\'s visual identity with the green accent color\\r\\n- Professional appearance suitable for commercial applications\\r\\n\\r\\n### 2. User Experience\\r\\n- Dark theme reduces eye strain in low-light environments\\r\\n- Light theme provides familiarity for traditional desktop apps\\r\\n- Smooth transitions between themes\\r\\n\\r\\n### 3. Developer Experience\\r\\n- Clear variable naming makes customization easy\\r\\n- Consistent design tokens across all components\\r\\n- Easy to extend with additional color variations\\r\\n\\r\\n### 4. Performance\\r\\n- Efficient color scheme with minimal variables\\r\\n- Optimized for both dark and light mode rendering\\r\\n\\r\\n## Customization Examples\\r\\n\\r\\n### Changing Accent Color\\r\\nTo use a different accent color, simply replace all instances of `#41cd52` with your preferred color:\\r\\n\\r\\n```json\\r\\n\\"Accent-color\\": \\"#0078d4\\",\\r\\n\\"Icons-color\\": \\"#0078d4\\",\\r\\n\\"QtDesignerIconsColor\\": \\"#0078d4\\"\\r\\n```\\r\\n\\r\\n### Adjusting Contrast\\r\\nFor higher contrast in the dark theme:\\r\\n```json\\r\\n\\"Background-color\\": \\"#121212\\",\\r\\n\\"Text-color\\": \\"#ffffff\\"\\r\\n```\\r\\n\\r\\n### Modifying Border Radius\\r\\nFor softer or sharper corners:\\r\\n```json\\r\\n\\"CARD_RADIUS\\": \\"8px\\"  // Softer\\r\\n\\"CARD_RADIUS\\": \\"16px\\" // Rounder\\r\\n```\\r\\n\\r\\n## Conclusion\\r\\n\\r\\nThese Qt Dark and Light themes provide a solid foundation for creating professional applications with custom widgets. The color schemes are carefully chosen to be both aesthetically pleasing and functionally effective, following modern design principles while staying true to Qt\'s visual identity.\\r\\n\\r\\nRemember to test your themes in different lighting conditions and consider user preferences when deciding which theme to set as default. The flexibility of this system allows you to easily create additional theme variations or customize the existing ones to match your specific application needs.\\r\\n\\r\\nFor more advanced theming options, refer to the Custom Widgets documentation on GitHub and explore additional styling variables available for specific widget types."},{"id":"qt-theme-styling-guide-qsscss-stylesheet","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-qsscss-stylesheet","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-qt-theme-styling-guide-qsscss-stylesheet.md","source":"@site/blog/2025-11-12-qt-theme-styling-guide-qsscss-stylesheet.md","title":"Qt Theme Styling Guide: Qss/Css Stylesheet","description":"This guide explains how to use the auto-generated theme variables in your QSS/SCSS files to create dynamic, theme-aware styles for your Qt applications.","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":false,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside6","description":"Posts about PySide6"},{"inline":false,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python","description":"Posts about Python"},{"inline":false,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui","description":"Posts about GUI"},{"inline":false,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets","description":"Posts about Custom Widgets"},{"inline":false,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial","description":"Posts about Tutorial"}],"readingTime":3.16,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"qt-theme-styling-guide-qsscss-stylesheet","tags":["PySide6","Python","GUI","Custom Widgets","Tutorial"],"title":"Qt Theme Styling Guide: Qss/Css Stylesheet"},"unlisted":false,"prevItem":{"title":"Qt Theme Styling Guide: Json Stylesheet","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-json-stylesheet"},"nextItem":{"title":"V 2.0.1 Released","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/v-201-released"}},"content":"This guide explains how to use the auto-generated theme variables in your QSS/SCSS files to create dynamic, theme-aware styles for your Qt applications.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## Understanding Auto-Generated Theme Variables\\r\\n\\r\\nWhen you define themes in your `style.json` file, the Custom Widgets system automatically generates SCSS variables that you can use throughout your stylesheets. These variables are created based on your theme colors and custom variables.\\r\\n\\r\\n### Core Color Variables\\r\\n\\r\\nThe system generates a comprehensive color palette from your base theme colors:\\r\\n\\r\\n- **Background colors**: `$COLOR_BACKGROUND_1` through `$COLOR_BACKGROUND_6` (6 shades from light to dark)\\r\\n- **Text colors**: `$COLOR_TEXT_1` through `$COLOR_TEXT_4` (4 shades from light to dark)  \\r\\n- **Accent colors**: `$COLOR_ACCENT_1` through `$COLOR_ACCENT_4` (4 shades from light to dark)\\r\\n- **RGB components**: Individual RGB values for each color (e.g., `$CB1_R`, `$CB1_G`, `$CB1_B` for background colors)\\r\\n\\r\\n### Additional Generated Variables\\r\\n\\r\\n- **Borders**: Pre-defined border styles (`$BORDER_1`, `$BORDER_2`, `$BORDER_3`)\\r\\n- **Selection borders**: Accent-colored borders (`$BORDER_SELECTION_1`, etc.)\\r\\n- **Border radius**: `$SIZE_BORDER_RADIUS`\\r\\n- **Tooltip opacity**: `$OPACITY_TOOLTIP`\\r\\n- **Resource paths**: `$PATH_RESOURCES`, `$RELATIVE_FOLDER`\\r\\n\\r\\n### Custom Theme Variables\\r\\n\\r\\nVariables defined in your JSON theme under `\\"Other-variables\\"` are also available:\\r\\n\\r\\n```json\\r\\n\\"Other-variables\\": {\\r\\n  \\"CARD_RADIUS\\": \\"12px\\",\\r\\n  \\"FOOTER_BG\\": \\"#0f0f0f\\",\\r\\n  \\"NAV_BG\\": \\"#1e1e1e\\"\\r\\n}\\r\\n```\\r\\n\\r\\n## Using Theme Variables in QSS/SCSS\\r\\n\\r\\n### Basic Widget Styling\\r\\n\\r\\n```scss\\r\\nQWidget {\\r\\n    background-color: $COLOR_BACKGROUND_1;\\r\\n    color: $COLOR_TEXT_1;\\r\\n}\\r\\n\\r\\nQPushButton {\\r\\n    background-color: $COLOR_ACCENT_1;\\r\\n    color: $COLOR_TEXT_1;\\r\\n    border-radius: $SIZE_BORDER_RADIUS;\\r\\n    border: $BORDER_1;\\r\\n}\\r\\n```\\r\\n\\r\\n### Creating Gradients with RGB Components\\r\\n\\r\\nUse the RGB variables to create dynamic gradients:\\r\\n\\r\\n```scss\\r\\nQFrame#gradientFrame {\\r\\n    background: qlineargradient(\\r\\n        x1:0, y1:0, x2:1, y2:1,\\r\\n        stop:0 rgba($CB1_R, $CB1_G, $CB1_B, 255),\\r\\n        stop:1 rgba($CB3_R, $CB3_G, $CB3_B, 255)\\r\\n    );\\r\\n}\\r\\n```\\r\\n\\r\\n### Component-Specific Styling\\r\\n\\r\\n```scss\\r\\n// Cards with custom radius\\r\\nQFrame#card {\\r\\n    background-color: $COLOR_BACKGROUND_2;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    border: $BORDER_2;\\r\\n}\\r\\n\\r\\n// Navigation elements\\r\\nQWidget#navigation {\\r\\n    background-color: $NAV_BG;\\r\\n}\\r\\n\\r\\n// Footer styling\\r\\nQWidget#footer {\\r\\n    background-color: $FOOTER_BG;\\r\\n}\\r\\n```\\r\\n\\r\\n### Complex Component Styling\\r\\n\\r\\nFor more complex components, you can create custom variables:\\r\\n\\r\\n```scss\\r\\n// Define custom gradients using theme variables\\r\\n$MY_GRADIENT: qlineargradient(\\r\\n    x1:0, y1:0, x2:1, y2:0.869,\\r\\n    stop:0 $COLOR_BACKGROUND_1,\\r\\n    stop:1 $COLOR_BACKGROUND_3\\r\\n);\\r\\n\\r\\nQMainWindow#customWindow {\\r\\n    background: $MY_GRADIENT;\\r\\n    \\r\\n    QPushButton {\\r\\n        background-color: $COLOR_ACCENT_2;\\r\\n        &:hover {\\r\\n            background-color: $COLOR_ACCENT_1;\\r\\n        }\\r\\n    }\\r\\n}\\r\\n```\\r\\n\\r\\n### Form Elements with Dynamic Borders\\r\\n\\r\\n```scss\\r\\nQLineEdit, QComboBox {\\r\\n    background-color: $COLOR_BACKGROUND_2;\\r\\n    border: 2px solid $COLOR_BACKGROUND_4;\\r\\n    border-radius: 8px;\\r\\n    padding: 8px;\\r\\n    \\r\\n    &:focus {\\r\\n        border-color: $COLOR_ACCENT_1;\\r\\n    }\\r\\n}\\r\\n```\\r\\n\\r\\n### Status Indicators\\r\\n\\r\\n```scss\\r\\n// Use accent colors for status indicators\\r\\n.status-success {\\r\\n    color: $COLOR_ACCENT_1;\\r\\n    border: 1px solid $COLOR_ACCENT_1;\\r\\n}\\r\\n\\r\\n.status-warning {\\r\\n    color: $COLOR_ACCENT_2;\\r\\n    border: 1px solid $COLOR_ACCENT_2;\\r\\n}\\r\\n\\r\\n.status-error {\\r\\n    color: $COLOR_ACCENT_3;\\r\\n    border: 1px solid $COLOR_ACCENT_3;\\r\\n}\\r\\n```\\r\\n\\r\\n## Best Practices\\r\\n\\r\\n### 1. Use Semantic Variable Names\\r\\nCreate meaningful variable names for your custom styles:\\r\\n\\r\\n```scss\\r\\n$CARD_BACKGROUND: $COLOR_BACKGROUND_2;\\r\\n$HEADER_TEXT: $COLOR_TEXT_1;\\r\\n$BUTTON_PRIMARY: $COLOR_ACCENT_1;\\r\\n```\\r\\n\\r\\n### 2. Leverage the Color Hierarchy\\r\\n- Use `$COLOR_BACKGROUND_1` for main backgrounds\\r\\n- Use `$COLOR_BACKGROUND_2` for cards and panels  \\r\\n- Use `$COLOR_BACKGROUND_3` for nested elements\\r\\n- Use accent colors for interactive elements\\r\\n\\r\\n### 3. Create Reusable Mixins\\r\\nFor complex styles, create SCSS mixins:\\r\\n\\r\\n```scss\\r\\n@mixin card-style {\\r\\n    background-color: $COLOR_BACKGROUND_2;\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    border: $BORDER_2;\\r\\n    padding: 16px;\\r\\n}\\r\\n\\r\\n.my-card {\\r\\n    @include card-style;\\r\\n}\\r\\n```\\r\\n\\r\\n### 4. Use RGB Components for Transparency\\r\\nCreate semi-transparent overlays using RGB variables:\\r\\n\\r\\n```scss\\r\\n.overlay {\\r\\n    background-color: rgba($CB1_R, $CB1_G, $CB1_B, 0.8);\\r\\n}\\r\\n```\\r\\n\\r\\n### 5. Theme-Aware Animations\\r\\nCreate animations that work with any theme:\\r\\n\\r\\n```scss\\r\\nQPushButton {\\r\\n    background-color: $COLOR_ACCENT_2;\\r\\n    transition: background-color 0.3s ease;\\r\\n    \\r\\n    &:hover {\\r\\n        background-color: $COLOR_ACCENT_1;\\r\\n    }\\r\\n}\\r\\n```\\r\\n\\r\\n## Dynamic Theme Switching\\r\\n\\r\\nWhen users switch themes, all variables are automatically updated, and your styles will reflect the new color scheme without any code changes.\\r\\n\\r\\n## Example: Complete Component\\r\\n\\r\\n```scss\\r\\n// Dashboard card component\\r\\n#DashboardCard {\\r\\n    background: qlineargradient(\\r\\n        x1:0, y1:0, x2:1, y2:1,\\r\\n        stop:0 $COLOR_BACKGROUND_2,\\r\\n        stop:1 $COLOR_BACKGROUND_3\\r\\n    );\\r\\n    border-radius: $CARD_RADIUS;\\r\\n    border: $BORDER_2;\\r\\n    \\r\\n    QLabel#title {\\r\\n        color: $COLOR_TEXT_1;\\r\\n        font-size: 16px;\\r\\n        font-weight: bold;\\r\\n    }\\r\\n    \\r\\n    QLabel#value {\\r\\n        color: $COLOR_ACCENT_1;\\r\\n        font-size: 24px;\\r\\n        font-weight: bold;\\r\\n    }\\r\\n    \\r\\n    QPushButton#action {\\r\\n        background-color: $COLOR_ACCENT_2;\\r\\n        color: $COLOR_TEXT_1;\\r\\n        border-radius: 6px;\\r\\n        padding: 8px 16px;\\r\\n        \\r\\n        &:hover {\\r\\n            background-color: $COLOR_ACCENT_1;\\r\\n        }\\r\\n    }\\r\\n}\\r\\n```\\r\\n\\r\\nBy using these auto-generated theme variables, you create styles that automatically adapt to any theme defined in your JSON configuration, ensuring consistency and making theme switching seamless for your users."},{"id":"v-201-released","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/v-201-released","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-12-v-201-released.md","source":"@site/blog/2025-11-12-v-201-released.md","title":"V 2.0.1 Released","description":"Qt Custom Widgets v2.0.1 Released","date":"2025-11-12T00:00:00.000Z","tags":[{"inline":false,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside6","description":"Posts about PySide6"},{"inline":false,"label":"Python","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/python","description":"Posts about Python"},{"inline":false,"label":"GUI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/gui","description":"Posts about GUI"},{"inline":false,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets","description":"Posts about Custom Widgets"},{"inline":false,"label":"Tutorial","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/tutorial","description":"Posts about Tutorial"},{"inline":false,"label":"version","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/version","description":"Posts about version"},{"inline":false,"label":"news","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/news","description":"Posts about news"}],"readingTime":2.02,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-12","slug":"v-201-released","tags":["PySide6","Python","GUI","Custom Widgets","Tutorial","version","news"],"title":"V 2.0.1 Released"},"unlisted":false,"prevItem":{"title":"Qt Theme Styling Guide: Qss/Css Stylesheet","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/qt-theme-styling-guide-qsscss-stylesheet"},"nextItem":{"title":"Introducing the New Dashboard UI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/introducing-the-new-dashboard-ui"}},"content":"## Qt Custom Widgets v2.0.1 Released\\r\\n\\r\\nWe\u2019re excited to announce the release of **Qt Custom Widgets 2.0.1** \u2014 a refined update that brings even more power and flexibility to your PyQt and PySide GUI development.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\nThis release focuses on **performance improvements**, **new custom widgets**, and a **streamlined command-line interface (CLI)** that now lets you launch Qt Designer with all custom widgets preloaded.\\r\\n\\r\\n---\\r\\n\\r\\n### What\u2019s New in 2.0.1\\r\\n\\r\\n#### More Custom Widgets\\r\\n\\r\\nThis version introduces several new widgets designed to enhance both functionality and design flexibility. Each widget can be used directly in Qt Designer or instantiated in Python code, fully integrated with your preferred Qt library (PySide6, PySide2, PyQt6, or PyQt5).\\r\\n\\r\\n#### Launch Qt Designer with Plugins\\r\\n\\r\\nThe new CLI now supports launching **Qt Designer** directly from your environment, with optional loading of all **Custom Widgets** plugins.\\r\\n\\r\\nTo open Designer with your custom widgets automatically loaded, simply run:\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --start-designer --plugins\\r\\n```\\r\\n\\r\\nIf you prefer to launch Designer without plugins, just run:\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --start-designer\\r\\n```\\r\\n\\r\\nThis feature ensures a seamless integration between your environment and Designer, making your workflow faster and more reliable.\\r\\n\\r\\n#### Improved JSON Stylesheet\\r\\n\\r\\nThe JSON-based stylesheet system has been updated for better theme management. You can now apply light, dark, or custom themes more efficiently with improved property mapping and rendering accuracy.\\r\\n\\r\\n#### Minor Fixes and Performance Improvements\\r\\n\\r\\nThis update includes improved logging, faster UI monitoring, and stability enhancements across all supported platforms.\\r\\n\\r\\n---\\r\\n\\r\\n### Updated Command-Line Interface (CLI)\\r\\n\\r\\nThe **Custom Widgets CLI** is designed to automate repetitive tasks in Qt development. It now supports file monitoring, UI conversion, Designer launching, and project setup \u2014 all in one tool.\\r\\n\\r\\n#### Monitor UI Files for Changes\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --monitor-ui path/to/file.ui --qt-library PySide6\\r\\n```\\r\\n\\r\\nAutomatically converts `.ui` files to Python when changes are detected.\\r\\n\\r\\n#### Convert UI Files to Python\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --convert-ui path/to/file.ui --qt-library PySide6\\r\\n```\\r\\n\\r\\nInstantly converts `.ui` files to `.py` while preserving all custom widget imports.\\r\\n\\r\\n#### Launch Designer\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --start-designer --plugins\\r\\n```\\r\\n\\r\\nOpens Qt Designer with **Custom Widgets** automatically loaded.\\r\\n\\r\\n#### Create a New Project\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --create-project\\r\\n```\\r\\n\\r\\nSets up a ready-to-use project structure for developing with **Qt Custom Widgets**.\\r\\n\\r\\nFor detailed command usage:\\r\\n\\r\\n```bash\\r\\nCustom_Widgets --help\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n### Upgrade Now\\r\\n\\r\\nTo upgrade to version 2.0.1, run:\\r\\n\\r\\n```bash\\r\\npip install --upgrade QT-PyQt-PySide-Custom-Widgets\\r\\n```\\r\\n\\r\\nOr visit the official PyPI page:\\r\\n[https://pypi.org/project/QT-PyQt-PySide-Custom-Widgets/](https://pypi.org/project/QT-PyQt-PySide-Custom-Widgets/)"},{"id":"introducing-the-new-dashboard-ui","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/introducing-the-new-dashboard-ui","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-07-introducing-the-new-dashboard-ui.md","source":"@site/blog/2025-11-07-introducing-the-new-dashboard-ui.md","title":"Introducing the New Dashboard UI","description":"We\u2019re excited to introduce the new modern Dashboard UI for the Docs-QT-PyQt-PySide-Custom-Widgets project!","date":"2025-11-07T00:00:00.000Z","tags":[{"inline":false,"label":"Dashboard","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/dashboard","description":"Posts about Dashboard"},{"inline":false,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside6","description":"Posts about PySide6"},{"inline":false,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets","description":"Posts about Custom Widgets"},{"inline":false,"label":"Design","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/design","description":"Posts about Design"}],"readingTime":0.96,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-07","slug":"introducing-the-new-dashboard-ui","tags":["Dashboard","PySide6","Custom Widgets","Design"],"title":"Introducing the New Dashboard UI"},"unlisted":false,"prevItem":{"title":"V 2.0.1 Released","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/v-201-released"},"nextItem":{"title":"Welcome to the Qt Custom Widgets Blog","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/welcome-to-the-qt-custom-widgets-blog"}},"content":"We\u2019re excited to introduce the **new modern Dashboard UI** for the *Docs-QT-PyQt-PySide-Custom-Widgets* project!\\nIt\u2019s built with **PySide6**, styled for dark mode, and designed to provide a seamless development experience.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Highlights\\n\\nHere\u2019s what\u2019s new in the Dashboard:\\n\\n- **Responsive layout** with sidebar, header, and content sections.  \\n- **Dark mode** optimized interface.  \\n- **Quick actions** to create and manage blog posts easily.  \\n- **Tailwind-inspired design** for better visual consistency.  \\n- **Modular includes** for sidebar, header, and footer \u2014 making it easy to reuse across pages.\\n\\n## Technologies\\n\\nThe dashboard is powered by:\\n- **PySide6** for UI logic  \\n- **Tailwind CSS** for layout styling  \\n- **Jinja templates** for component structure  \\n- **Docusaurus** for the documentation and blog system\\n\\n## Upcoming Features\\n\\nNext, we\u2019re adding:\\n- Markdown live preview for blog creation.  \\n- Automatic `.md` generation from the dashboard form.  \\n- Post synchronization with your hosted docs site at  \\n [spinncompany.github.io/Docs-QT-PyQt-PySide-Custom-Widgets/blog](https://spinncompany.github.io/Docs-QT-PyQt-PySide-Custom-Widgets/blog)\\n\\n## Final Thoughts\\n\\nThis marks the beginning of a unified workflow \u2014 write, preview, and publish your documentation or blogs directly from the **Dashboard UI**.\\n\\nStay tuned for the next update:  \\n> \u201cHow We Integrated Docusaurus Build Automation with PySide6 Backend\u201d"},{"id":"welcome-to-the-qt-custom-widgets-blog","metadata":{"permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/welcome-to-the-qt-custom-widgets-blog","editUrl":"https://github.com/SpinnCompany/Docs-QT-PyQt-PySide-Custom-Widgets/tree/main/blog/2025-11-07-welcome-to-the-qt-custom-widgets-blog.md","source":"@site/blog/2025-11-07-welcome-to-the-qt-custom-widgets-blog.md","title":"Welcome to the Qt Custom Widgets Blog","description":"Welcome to the official Qt Custom Widgets Blog, hosted on Spinncode!","date":"2025-11-07T00:00:00.000Z","tags":[{"inline":false,"label":"Qt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/qt","description":"Posts about Qt"},{"inline":false,"label":"PySide6","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyside6","description":"Posts about PySide6"},{"inline":false,"label":"PyQt","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/pyqt","description":"Posts about PyQt"},{"inline":false,"label":"Custom Widgets","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/custom-widgets","description":"Posts about Custom Widgets"},{"inline":false,"label":"Docusaurus","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/tags/docusaurus","description":"Posts about Docusaurus"}],"readingTime":1.45,"hasTruncateMarker":true,"authors":[{"name":"Khamisi Kibet","title":"Creator of Qt Custom Widgets","url":"https://github.com/SpinnCompany","email":"khamisikibet@gmail.com","imageURL":"https://github.com/SpinnCompany.png","key":"Khamisi Kibet","page":null}],"frontMatter":{"authors":["Khamisi Kibet"],"date":"2025-11-07","slug":"welcome-to-the-qt-custom-widgets-blog","tags":["Qt","PySide6","PyQt","Custom Widgets","Docusaurus"],"title":"Welcome to the Qt Custom Widgets Blog"},"unlisted":false,"prevItem":{"title":"Introducing the New Dashboard UI","permalink":"/Docs-QT-PyQt-PySide-Custom-Widgets/blog/introducing-the-new-dashboard-ui"}},"content":"Welcome to the official **Qt Custom Widgets Blog**, hosted on [Spinncode](https://customwidgets.org)!\\n\\nThis space is dedicated to sharing tutorials, behind-the-scenes updates, and deep dives into **modern PySide6 and PyQt widget design**.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Why This Blog Exists\\n\\nWhen building modern desktop apps with Qt for Python, you quickly realize that many of the best UI ideas need custom widgets \u2014 not just the defaults.  \\nThis blog will help you:\\n- Learn how to design and implement reusable custom widgets.\\n- Explore advanced PySide6 and PyQt UI techniques.\\n- Follow development updates for the **Docs-QT-PyQt-PySide-Custom-Widgets** module.\\n\\nWhether you\u2019re creating dashboards, admin panels, or interactive desktop tools \u2014 you\u2019ll find practical examples here.\\n\\n## What You Can Expect\\n- Step-by-step widget tutorials\\n- Modern UI design ideas\\n- Integration tips for Docusaurus documentation\\n- Community discussions & new releases\\n\\nOur upcoming posts will include topics like:\\n- Building **Dynamic Progress Bars** with QProperty animations.\\n- Creating **Designer-friendly Widgets** with custom properties.\\n- Structuring PySide6 projects for maintainability and scalability.\\n\\n## About the Project\\n\\nThe **Docs-QT-PyQt-PySide-Custom-Widgets** project is a growing toolkit of pre-built, stylized Qt widgets that you can use in your apps or preview in Qt Designer.  \\nIt includes:\\n- Ready-made reusable widgets\\n- Integrated resource management\\n- A project generator (\u201cProject Maker\u201d) for faster setup\\n\\nYou can explore the docs at  \\n [https://spinncompany.github.io/Docs-QT-PyQt-PySide-Custom-Widgets](https://spinncompany.github.io/Docs-QT-PyQt-PySide-Custom-Widgets)\\n\\n## \u200d About the Author\\n\\nI\u2019m **Khamisi Kibet**, a Python developer from Kenya passionate about creating **modern, lightweight desktop UIs**.\\nI believe in building one line of code at a time \u2014 clean, efficient, and scalable.\\n\\nFollow updates here or on [Spinncode.com](https://customwidgets.org).\\n\\n---\\n\\n> *\u201cDesign it once, use it everywhere \u2014 from Designer to production.\u201d*\\n> \u2014 *Qt Custom Widgets Team*"}]}}')}}]);